const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
function formatText(value){const text=esc(value).replace(/\r?\n/g,'<br>');const linked=text.replace(/(^|[\s(])((?:https?:\/\/|www\.)[^\s<]+)/gi,(m,p,u)=>`${p}<a class="text-link" href="${u.startsWith('www.')?'https://'+u:u}" target="_blank" rel="noopener noreferrer">${u}</a>`);return linked.replace(/(^|[\s>])@([a-zA-Z0-9_]{3,32})\b/g,(m,p,u)=>`${p}<button type="button" class="mention" data-username="${u}">@${u}</button>`)}
function formatBotText(value){const safe=formatText(value);return safe.replace(/(^|[\s>])\/([a-zA-Z][a-zA-Z0-9_]{0,31})(@[a-zA-Z0-9_]{3,32})?/g,(m,p,cmd,mention)=>`${p}<button type="button" class="bot-command-link" data-bot-command="/${cmd}${mention||''}">/${cmd}${mention||''}</button>`)}
function renderBotCommandLinks(root){root?.querySelectorAll('[data-bot-command]').forEach(b=>b.onclick=async()=>{const cmd=b.dataset.botCommand;if(!current||!cmd)return;try{const out=await api('/api/messages',{method:'POST',body:JSON.stringify({conversationId:current.id,text:cmd})});appendMessage(out);scrollBottom()}catch(e){showToast(e.message,true)}})}
const avatar=(u,cls='avatar')=>u?.avatar?`<div class="${cls}"><img src="${esc(backendUrl(u.avatar))}"></div>`:`<div class="${cls}">${esc((u?.display_name||'گ')[0])}</div>`;
const CALL_ICE=[{urls:'stun:stun.l.google.com:19302'},{urls:'stun:stun1.l.google.com:19302'}];
function showToast(msg,error=false){const t=$('toast');t.textContent=msg;t.className='toast show'+(error?' error':'');clearTimeout(showToast.t);showToast.t=setTimeout(()=>t.className='toast',4200)}
window.addEventListener('error',e=>{if(e?.error?.message)showToast(e.error.message,true)});
function api(url,opt={}){opt.headers={...(opt.headers||{}),...(token?{Authorization:'Bearer '+token}:{})};if(opt.body&&!(opt.body instanceof FormData))opt.headers['Content-Type']='application/json';return fetch(backendUrl(url),opt).then(async r=>{const ct=r.headers.get('content-type')||'';const d=ct.includes('application/json')?await r.json().catch(()=>({})):{};if(!r.ok)throw Error(d.error||`خطا (${r.status})`);return d})}
function refreshUserUI(){
  if(!me)return;
  const name=me.display_name||me.name||'کاربر';
  const username=me.username?('@'+me.username):'';
  const dn=$('drawerName'); if(dn)dn.textContent=name;
  const du=$('drawerUser'); if(du)du.textContent=username;
  const avatarEl=$('drawerAvatar');
  if(avatarEl){
    if(me.avatar) avatarEl.innerHTML=`<img src="${esc(backendUrl(me.avatar))}" alt="">`;
    else avatarEl.textContent=(name[0]||'گ');
  }
  const profileUser=$('profileUser'); if(profileUser)profileUser.textContent=username;
  const profileName=$('profileName'); if(profileName && document.activeElement!==profileName)profileName.value=name;
  const profileUsername=$('profileUsername'); if(profileUsername && document.activeElement!==profileUsername)profileUsername.value=me.username||'';
  const profileBio=$('profileBio'); if(profileBio && document.activeElement!==profileBio)profileBio.value=me.bio||'';
}
function showAuth(){$('auth').classList.remove('hidden');$('app').classList.add('hidden')}function showApp(){$('auth').classList.add('hidden');$('app').classList.remove('hidden')}
function enterChatView(){document.getElementById('app')?.classList.add('chat-open')}
function leaveChatView(){const app=document.getElementById('app');app?.classList.remove('chat-open');current=null;document.getElementById('chatTitle')?.replaceChildren(document.createTextNode('زنتو'));document.getElementById('chatStatus')?.replaceChildren(document.createTextNode('یک گفتگو را انتخاب کنید'));document.getElementById('messages')?.replaceChildren(Object.assign(document.createElement('div'),{className:'empty',innerHTML:'<div class="empty-icon">✈</div><b>زنتو</b><span>یک گفتگو را از فهرست انتخاب کن</span>'}));renderConvs?.()}
