function notificationTone(){
  try{const type=settings?.notifications?.sound||'default';const C=window.AudioContext||window.webkitAudioContext;if(!C)return;const ctx=new C();const notes=type==='soft'?[660]:type==='pop'?[880,1175]:[660,880,660];notes.forEach((f,i)=>{const o=ctx.createOscillator(),g=ctx.createGain();o.frequency.value=f;o.type='sine';g.gain.value=.035;o.connect(g);g.connect(ctx.destination);o.start(ctx.currentTime+i*.08);o.stop(ctx.currentTime+i*.08+.07)});setTimeout(()=>ctx.close().catch(()=>{}),500)}catch{}
}
async function setupBrowserNotifications(){
  if(!('Notification' in window))return;
  if(settings?.notifications?.messages!==false && Notification.permission==='default'){
    try{await Notification.requestPermission()}catch{}
  }
  if('serviceWorker' in navigator){try{const reg=await navigator.serviceWorker.ready;const key=window.ZENTO_CONFIG?.VAPID_PUBLIC_KEY;if(key&&reg.pushManager){let sub=await reg.pushManager.getSubscription();if(!sub){sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:urlBase64ToUint8Array(key)})}await api('/api/push/subscribe',{method:'POST',body:JSON.stringify({subscription:sub.toJSON()})})}}catch(e){console.warn('push setup',e.message)}}
}
function urlBase64ToUint8Array(base64String){const padding='='.repeat((4-base64String.length%4)%4),base64=(base64String+padding).replace(/-/g,'+').replace(/_/g,'/');const raw=atob(base64);return Uint8Array.from([...raw].map(c=>c.charCodeAt(0)))}
function maybeNotifyMessage(m){
  if(!settings?.notifications?.messages||Number(m.sender_id)===Number(me?.id))return;
  if(settings?.notifications?.sounds!==false)notificationTone();
  if(document.visibilityState==='visible' || !('Notification' in window) || Notification.permission!=='granted')return;
  try{const sender=m.bot_name||m.display_name||m.username||'پیام جدید';const body=settings?.notifications?.previews===false?'پیام جدید':(m.text||'رسانه جدید');new Notification(sender,{body:String(body).slice(0,140),icon:m.avatar?backendUrl(m.avatar):'/zento-icon.png',tag:'zento-msg-'+m.id})}catch{}
}
async function boot(){
 if(!token)return showAuth();
 try{me=await api('/api/me');
   if(me?.role==='superadmin'){showApp();document.body.classList.add('performance-fast');openSuperAdmin();return;}
   showApp();document.body.classList.add('performance-fast');leaveChatView();refreshUserUI();await loadSettings();connectSocket();await Promise.all([loadConvs(),setupBrowserNotifications()]);
 }catch(e){localStorage.removeItem('zento_token');token=null;showAuth();showToast(e.message,true)}
}
async function openSuperAdmin(){
  document.body.classList.add('superadmin-mode');
  const shell=document.createElement('div'); shell.id='superAdminPanel'; shell.className='superadmin-panel';
  shell.innerHTML=`<div class="sa-shell"><header class="sa-head"><div><span class="sa-kicker">ZENTO CONTROL CENTER</span><h1>🛡️ پنل مدیریت سازنده</h1><p>کنترل کامل کاربران، گفتگوها، تماس‌ها و درخواست‌های پشتیبانی</p></div><button id="saLogout" class="sa-logout">🚪 خروج</button></header><section id="saStats" class="sa-stats"><div class="sa-loading">در حال بارگذاری داشبورد…</div></section><nav class="sa-tabs"><button class="active" data-sa-tab="overview">📊 نمای کلی</button><button data-sa-tab="users">👥 کاربران</button><button data-sa-tab="chats">💬 گفتگوها</button><button data-sa-tab="calls">📞 تماس‌ها</button><button data-sa-tab="support">🎧 پشتیبانی</button></nav><main id="saBody" class="sa-body"></main></div>`;
  document.body.appendChild(shell); $('saLogout').onclick=()=>{localStorage.removeItem('zento_token');token=null;location.reload()};
  shell.querySelectorAll('[data-sa-tab]').forEach(b=>b.onclick=()=>{shell.querySelectorAll('[data-sa-tab]').forEach(x=>x.classList.toggle('active',x===b));renderSuperAdminTab(b.dataset.saTab)});
  await renderSuperAdminTab('overview');
}
