async function renderSuperAdminTab(tab){const body=$('saBody');if(!body)return;body.innerHTML='<div class="sa-loading">در حال دریافت اطلاعات…</div>';try{if(!superAdminData)await loadSuperAdmin();const d=superAdminData;if(tab==='overview'){ $('saStats').innerHTML=saStat('کاربران',d.stats.users,'👥')+saStat('گفتگوها',d.stats.conversations,'💬')+saStat('پیام‌ها',d.stats.messages,'✉️')+saStat('تماس‌ها',d.stats.calls,'📞')+saStat('درخواست پشتیبانی',d.stats.support,'🎧'); body.innerHTML=`<div class="sa-grid2"><section class="sa-card"><div class="sa-card-head"><b>کاربران اخیر</b><button data-sa-tab-jump="users">مشاهده همه</button></div><div class="sa-list">${d.recentUsers.map(u=>`<div class="sa-row">${avatar(u,'sa-avatar')}<div><b>${esc(u.display_name||'کاربر')}</b><small>@${esc(u.username||'')} · ${esc(u.email||'')}</small></div><span>${new Date(u.created_at).toLocaleDateString('fa-IR')}</span></div>`).join('')||'<div class="sa-empty">کاربری وجود ندارد.</div>'}</div></section><section class="sa-card"><div class="sa-card-head"><b>آخرین تماس‌ها</b><button data-sa-tab-jump="calls">مشاهده همه</button></div><div class="sa-list">${d.recentCalls.map(c=>`<div class="sa-row"><div class="sa-call-icon">${c.status==='completed'?'📞':'📵'}</div><div><b>${esc(c.caller_name||'کاربر')} ← ${esc(c.receiver_name||'کاربر')}</b><small>${esc(c.status||'')} · ${Number(c.duration||0)} ثانیه</small></div><span>${new Date(c.created_at).toLocaleDateString('fa-IR')}</span></div>`).join('')||'<div class="sa-empty">تماسی ثبت نشده.</div>'}</div></section></div>`;body.querySelectorAll('[data-sa-tab-jump]').forEach(b=>b.onclick=()=>{shellTab(b.dataset.saTabJump)})}else if(tab==='users'){const users=await api('/api/admin/users');body.innerHTML=`<section class="sa-card"><div class="sa-card-head"><div><b>مدیریت کاربران</b><small>${users.length} مورد اخیر</small></div><input id="saUserSearch" placeholder="جستجوی نام، ایمیل یا نام کاربری…"></div><div id="saUsersList" class="sa-list">${users.map(u=>`<div class="sa-row sa-user-row" data-search="${esc((u.display_name||'')+' '+(u.username||'')+' '+(u.email||''))}">${avatar(u,'sa-avatar')}<div><b>${esc(u.display_name||'کاربر')}</b><small>@${esc(u.username||'')} · ${esc(u.email||'')}</small></div><span class="sa-badge">${u.is_bot?'ربات':'کاربر'}</span></div>`).join('')}</div></section>`;$('saUserSearch').oninput=e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('.sa-user-row').forEach(r=>r.classList.toggle('hidden',!r.dataset.search.toLowerCase().includes(q)))}}else if(tab==='chats'){const rows=await api('/api/admin/conversations');body.innerHTML=`<section class="sa-card"><div class="sa-card-head"><b>همه گفتگوها</b><small>${rows.length} مورد اخیر</small></div><div class="sa-list">${rows.map(c=>`<div class="sa-row"><div class="sa-call-icon">${c.type==='channel'?'📢':c.type==='group'?'👥':'💬'}</div><div><b>${esc(c.name||'گفتگوی خصوصی')}</b><small>${esc(c.type)} · ${Number(c.members||0)} عضو${c.username?' · @'+esc(c.username):''}</small></div><span>#${c.id}</span></div>`).join('')}</div></section>`}else if(tab==='calls'){body.innerHTML=`<section class="sa-card"><div class="sa-card-head"><b>تاریخچه تماس‌ها</b><button id="saRefresh">↻ تازه‌سازی</button></div><div class="sa-list">${d.recentCalls.map(c=>`<div class="sa-row"><div class="sa-call-icon">${c.status==='completed'?'📞':'📵'}</div><div><b>${esc(c.caller_name||'کاربر')} ← ${esc(c.receiver_name||'کاربر')}</b><small>وضعیت: ${esc(c.status||'-')} · مدت: ${Number(c.duration||0)} ثانیه</small></div><span>${new Date(c.created_at).toLocaleString('fa-IR')}</span></div>`).join('')}</div></section>`;$('saRefresh').onclick=async()=>{superAdminData=null;await renderSuperAdminTab('calls')}}else if(tab==='support'){body.innerHTML=`<section class="sa-card"><div class="sa-card-head"><b>درخواست‌های پشتیبانی</b><small>${d.support.length} مورد اخیر</small></div><div class="sa-list">${d.support.map(x=>`<article class="sa-support"><div><b>${esc(x.subject||'بدون موضوع')}</b><small>${esc(x.display_name||'کاربر')} · ${esc(x.email||'')} · ${new Date(x.created_at).toLocaleString('fa-IR')}</small></div><p>${esc(x.message||'')}</p></article>`).join('')||'<div class="sa-empty">درخواستی وجود ندارد.</div>'}</div></section>`}}catch(e){body.innerHTML=`<div class="sa-error">${esc(e.message)}</div>`}}
function shellTab(tab){document.querySelectorAll('[data-sa-tab]').forEach(x=>x.classList.toggle('active',x.dataset.saTab===tab));renderSuperAdminTab(tab)}

let convRefreshTimer=null;
function scheduleConvRefresh(){clearTimeout(convRefreshTimer);convRefreshTimer=setTimeout(()=>loadConvs().catch(()=>{}),180)}
function connectSocket(){
 socket=io(BACKEND_URL||undefined,{auth:{token},transports:['websocket','polling'],upgrade:true,reconnection:true,reconnectionAttempts:Infinity,reconnectionDelay:300,reconnectionDelayMax:3000});
 socket.on('connect_error',e=>console.warn('socket',e.message));
 socket.on('message',m=>{if(Number(m.sender_id)!==Number(me?.id)&&settings?.notifications?.sounds!==false)notificationTone();if(current&&Number(m.conversation_id)===Number(current.id))appendMessage(m);else maybeNotifyMessage(m);scheduleConvRefresh()});
 socket.on('reaction',d=>{const el=document.querySelector(`[data-msg="${d.messageId}"]`);if(el)renderReactions(el,d.reactions)});
 socket.on('message_deleted',id=>{delete messageCache[id];document.querySelector(`[data-msg="${id}"]`)?.remove()});
 socket.on('message_hidden',id=>{delete messageCache[id];document.querySelector(`[data-msg="${id}"]`)?.remove()});
 socket.on('read_receipt',d=>{if(current&&Number(d.conversationId)===Number(current.id))document.querySelectorAll('.mine .msg-status').forEach(x=>{x.textContent='✓✓';x.classList.add('read')})});
 socket.on('member_removed',d=>{if(current&&Number(current.id)===Number(d.conversationId)&&Number(d.userId)===Number(me.id)){showToast('از این گفتگو حذف شدید',true);current=null;loadConvs();$('messages').innerHTML='<div class="empty"><b>عضویت شما پایان یافت</b></div>'}});
 socket.on('typing',d=>{if(current)$('typing').textContent=d.typing?'در حال نوشتن…':''});
 installCallHandlers();
}
async function loadSettings(){try{settings=await api('/api/settings');settings.notifications??={};settings.calls??={};settings.data_usage??={};settings.privacy??={};settings.security??={};settings.appearance??={}}catch{settings={notifications:{messages:true,sounds:true,previews:true},calls:{ringtone:'classic',ringVolume:.8,conferenceTone:true},data_usage:{autoplay:true,autoDownloadImages:true,autoDownloadVideos:false,autoDownloadAudio:false},privacy:{lastSeen:'everyone',profilePhoto:'everyone',readReceipts:true},security:{twoStep:false}}}}
async function loadConvs(){convs=await api('/api/conversations');renderConvs();renderStoryTopBar().catch(e=>console.warn('stories',e));await handleJoinHash()}
async function handleJoinHash(){const m=location.hash.match(/^#\/join\/([^/]+)$/);if(!m)return;try{const info=await api('/api/public/conversations/'+encodeURIComponent(m[1]));const c=await api('/api/conversations/'+info.id+'/join',{method:'POST'});await loadConvs();openConv(c.id);history.replaceState(null,'',location.pathname+location.search)}catch(e){showToast(e.message,true)}}
async function stage2HandleMessageHash(){
  if(!token)return;
  const m=location.hash.match(/^#\/msg\/(\d+)\/(\d+)$/); if(!m)return;
  const cid=Number(m[1]), mid=Number(m[2]);
  try{
    if(!convs.length) await loadConvs();
    if(!convs.some(c=>Number(c.id)===cid)) return showToast('این گفتگو برای حساب شما در دسترس نیست',true);
    await openConv(cid);
    setTimeout(()=>{
      const row=document.querySelector(`[data-msg="${mid}"]`);
      if(row){row.scrollIntoView({behavior:'smooth',block:'center'});row.classList.add('stage2-highlight');setTimeout(()=>row.classList.remove('stage2-highlight'),1800)}
      else showToast('پیام پیدا نشد یا حذف شده است',true);
    },120);
  }catch(e){showToast(e.message,true)}
}
window.addEventListener('hashchange',handleJoinHash);
window.addEventListener('hashchange',stage2HandleMessageHash)
function renderConvs(){const list=(activeFilter==='all'?convs:convs.filter(c=>c.type===activeFilter)).sort((a,b)=>Number(!!b._pinned)-Number(!!a._pinned));$('chats').innerHTML=list.map(c=>{const other=c.type==='direct'?c.members.find(x=>Number(x.id)!==Number(me.id)):null;const title=c.type==='direct'?(other?.display_name||'گفتگو'):c.name;const icon=c.type==='channel'?'📢':c.type==='group'?'👥':'گ';return `<button class="chat-item ${current&&Number(current.id)===Number(c.id)?'active':''}" data-id="${c.id}">${c.type==='direct'?avatar(other):`<div class="avatar">${icon}</div>`}<div class="ci"><b>${esc(title)}</b><small>${c.type==='channel'?'کانال':c.type==='group'?`${c.members.length} عضو`:'@'+esc(other?.username||'')} · ${esc(c.last_text||'')}</small></div><span class="type-badge">${c.unread_count>0?`<b class="unread-badge">${c.unread_count>99?'99+':c.unread_count}</b>`:''}${c.type==='channel'?'کانال':c.type==='group'?'گروه':'خصوصی'}</span></button>`}).join('')||'<div class="empty"><span>گفتگویی پیدا نشد</span></div>'}
$('chats').onclick=e=>{const x=e.target.closest('.chat-item');if(!x)return;if(x.dataset.saved==='1')return openSaved();openConv(Number(x.dataset.id))};
function refreshBotCommandsPanel(){
 const panel=$('botCommandsPanel'),toggle=$('botCommandsToggle');if(!panel||!toggle)return;
 const other=current?.type==='direct'?current.members?.find(x=>Number(x.id)!==Number(me.id)):null;
 const isBot=!!other?.is_bot;toggle.classList.toggle('hidden',!isBot);
 if(!isBot){panel.classList.add('hidden');panel.innerHTML='';return}
 const candidates=Object.values(messageCache||{}).filter(m=>Number(m.conversation_id)===Number(current?.id)&&m.bot_id&&m.reply_markup&&!m.deleted);
 const latest=candidates.sort((a,b)=>Number(a.id)-Number(b.id)).pop();
 if(!latest){panel.innerHTML='<div class="bot-commands-empty">🤖 ربات هنوز دکمه‌ای برای نمایش نفرستاده است.</div>';return}
 panel.innerHTML=renderBotMarkup(latest.reply_markup,latest.id)||'<div class="bot-commands-empty">🤖 برای این ربات دکمه‌ای ثبت نشده است.</div>';
 panel.querySelectorAll('[data-bot-reply]').forEach(b=>b.onclick=async()=>{const text=b.dataset.botReply;if(!text)return;try{b.disabled=true;const out=await api('/api/messages',{method:'POST',body:JSON.stringify({conversationId:current.id,text})});appendMessage(out);scrollBottom()}catch(e){showToast(e.message,true)}finally{b.disabled=false}});
 panel.querySelectorAll('[data-bot-url]').forEach(b=>b.onclick=()=>window.open(b.dataset.botUrl,'_blank','noopener,noreferrer'));
 panel.querySelectorAll('[data-bot-inline]').forEach(b=>b.onclick=async()=>{try{b.disabled=true;await api('/api/messages/'+Number(b.dataset.msgId)+'/bot-button',{method:'POST',body:JSON.stringify({buttonIndex:Number(b.dataset.buttonIndex)})});showToast('دکمه اجرا شد ✓')}catch(e){showToast(e.message,true)}finally{b.disabled=false}});
}
function toggleBotCommands(){const p=$('botCommandsPanel');if(!p)return;p.classList.toggle('hidden');refreshBotCommandsPanel();if(!p.classList.contains('hidden'))p.classList.remove('hidden')}
function updateBotChatUI(){const bar=$('botStartBar'),btn=$('botStartButton'),a=$('callAudio'),v=$('callVideo'),t=$('botCommandsToggle');if(!bar)return;const other=current?.type==='direct'?current.members?.find(x=>Number(x.id)!==Number(me.id)):null;const isBot=!!other?.is_bot;bar.classList.toggle('hidden',!isBot);if(isBot){btn.textContent='▶ شروع';btn.onclick=async()=>{btn.disabled=true;try{const out=await api('/api/messages',{method:'POST',body:JSON.stringify({conversationId:current.id,text:'/start'})});bar.classList.add('hidden');appendMessage(out);scrollBottom();$('text').focus()}catch(e){showToast(e.message,true)}finally{btn.disabled=false}}}a?.classList.toggle('hidden',isBot);v?.classList.toggle('hidden',isBot);t?.classList.toggle('hidden',!isBot);if(isBot)refreshBotCommandsPanel();else $('botCommandsPanel')?.classList.add('hidden')}

async function openConv(id){const found=convs.find(c=>Number(c.id)===Number(id));if(!found)return;current=found;enterChatView();renderConvs();if(socket?.connected)socket.emit('join',current.id);const other=current.type==='direct'?current.members.find(x=>Number(x.id)!==Number(me.id)):null;$('chatAvatar').outerHTML=`<div id="chatAvatar" class="avatar">${current.type==='direct'?(other?.avatar?`<img src="${esc(backendUrl(other.avatar))}">`:esc((other?.display_name||'گ')[0])):(current.type==='channel'?'📢':'👥')}</div>`;$('chatTitle').textContent=current.type==='direct'?(other?.display_name||'گفتگو'):current.name;$('chatStatus').textContent=current.type==='channel'?`📢 ${current.members.length} عضو`:current.type==='group'?`👥 ${current.members.length} عضو`:`@${other?.username||''}`;document.querySelector('#chatAvatar')?.addEventListener('click',()=>current.type==='direct'&&other?openUserProfile(other.id):openConversationInfo(current));$('chatTitle').onclick=current.type==='direct'&&other?()=>openUserProfile(other.id):(current.type==='group'||current.type==='channel'?()=>openConversationInfo(current):null); $('chatMore').classList.toggle('hidden',!(current.type==='group'||current.type==='channel')); if(current.type==='group'||current.type==='channel'){try{await api(`/api/conversations/${current.id}/management`);$('chatMore').classList.remove('hidden')}catch{$('chatMore').classList.add('hidden')}}const can=current.type!=='channel'||Number(current.owner_id)===Number(me.id);$('text').disabled=!can;$('send').disabled=!can;$('voice').disabled=!can;$('text').placeholder=can?'پیامی بنویس...':'این کانال فقط برای مشاهده است';$('messages').innerHTML='<div class="empty">در حال بارگذاری…</div>';try{const [ms]=await Promise.all([api(`/api/conversations/${id}/messages`),api(`/api/conversations/${id}/read`,{method:'POST'}).catch(()=>null)]);$('messages').innerHTML='';found.unread_count=0;if(!ms.length)$('messages').innerHTML='<div class="empty"><b>شروع گفتگو</b><span>اولین پیام را بفرست 👋</span></div>';ms.forEach(appendMessage);scrollBottom();if(innerWidth<851)$('sidebar').classList.remove('open')}catch(e){$('messages').innerHTML=`<div class="empty"><b>خطا در باز کردن گفتگو</b><span>${esc(e.message)}</span></div>`}updateBotChatUI()}
function renderBotMarkup(markup,messageId){
  if(!markup||typeof markup!=='object')return '';
  if(markup.remove_keyboard)return '';
  const rows=Array.isArray(markup.inline_keyboard)?markup.inline_keyboard:Array.isArray(markup.keyboard)?markup.keyboard:null;
  if(!rows?.length)return '';
  const inline=Array.isArray(markup.inline_keyboard);
  return `<div class="bot-keyboard ${inline?'bot-inline-keyboard':'bot-reply-keyboard'}">${rows.map((row,ri)=>`<div class="bot-keyboard-row">${(Array.isArray(row)?row:[]).map((b,ci)=>{
    const text=esc(String(b?.text||'دکمه'));
    if(b?.url)return `<button type="button" class="bot-keyboard-btn" data-bot-url="${esc(String(b.url))}">${text}</button>`;
    if(inline)return `<button type="button" class="bot-keyboard-btn" data-bot-inline="1" data-msg-id="${Number(messageId)}" data-button-index="${ri*100+ci}">${text}</button>`;
    return `<button type="button" class="bot-keyboard-btn" data-bot-reply="${esc(String(b?.text||''))}">${text}</button>`;
  }).join('')}</div>`).join('')}</div>`;
}

function appendMessage(m){if(!current||Number(m.conversation_id)!==Number(current.id)||document.querySelector(`[data-msg="${m.id}"]`))return;const row=document.createElement('div');const mine=Number(m.sender_id)===Number(me.id);row.className='bubble-row '+(mine?'mine':'');row.dataset.msg=m.id;const sender=m.bot_name||m.display_name||m.username||'کاربر';let body='';if(m.text?.startsWith('[[ZENTO_ARTICLE]]')){try{const a=JSON.parse(m.text.slice(17));body=`<article class="message-article"><h3>${esc(a.title)}</h3><p>${formatText(a.body)}</p></article>`}catch{body=formatText(m.text)}}else if(m.text?.startsWith('[[ZENTO_POLL]]')){try{const p=JSON.parse(m.text.slice(14));body=`<div class="message-poll"><h4>📊 ${esc(p.question)}</h4>${p.options.map((o,i)=>`<button class="poll-choice" data-poll-index="${i}">${esc(o)}<span>○</span></button>`).join('')}</div>`}catch{body=formatText(m.text)}}else if(m.text?.startsWith('[[ZENTO_LOCATION]]')){try{const l=JSON.parse(m.text.slice(18));body=`<button class="message-location" data-lat="${esc(l.lat)}" data-lon="${esc(l.lon)}">📍 مشاهده موقعیت<br><small>${esc(l.lat)}, ${esc(l.lon)}</small></button>`}catch{body=formatText(m.text)}}if(m.reply_to)body+=`<div class="reply-ref">↩ پاسخ به: ${esc(m.text||'پیام چندرسانه‌ای')}</div>`;if(m.kind==='voice')body+=mediaAudio(m.file_url,true,m.file_name,m.id);else if(m.file_url&&m.file_type?.startsWith('image/'))body+=`<button type="button" class="media-card custom-media-trigger image-message-card" data-media-kind="image" data-media-url="${esc(backendUrl(m.file_url))}" data-media-title="${esc(m.file_name||'تصویر')}"><img src="${esc(backendUrl(m.file_url))}" alt="تصویر"><span class="media-overlay-label">⤢ باز کردن تصویر</span></button><a class="download-btn" download href="${esc(backendUrl('/api/media/download/'+m.id))}">دانلود تصویر ⬇</a>`;else if(m.file_url&&m.file_type?.startsWith('video/'))body+=`<button type="button" class="media-card custom-media-trigger video-message-card" data-media-kind="video" data-media-url="${esc(backendUrl(m.file_url))}" data-media-title="${esc(m.kind==='video'?'ویدیو مسیج':m.file_name||'ویدیو')}"><span class="video-thumb-placeholder">▶</span><span class="media-overlay-label">▶ پخش ${m.kind==='video'?'ویدیو مسیج':'ویدیو'}</span></button><a class="download-btn" download href="${esc(backendUrl('/api/media/download/'+m.id))}">دانلود ویدیو ⬇</a>`;else if(m.file_url&&m.file_type?.startsWith('audio/'))body+=mediaAudio(m.file_url,false,m.file_name,m.id);else if(m.file_url){const isPdf=m.file_type==='application/pdf'||/\.pdf$/i.test(m.file_name||'');body+=`<button type="button" class="file-card custom-media-trigger" data-media-kind="${isPdf?'document':'document'}" data-media-url="${esc(backendUrl(m.file_url))}" data-media-title="${esc(m.file_name||'سند')}"><span>${isPdf?'📕':'📄'}</span><div class="file-name">${esc(m.file_name||'فایل')}</div><small>باز کردن در نمایشگر زنتو</small></button><a class="download-btn" download href="${esc(backendUrl('/api/media/download/'+m.id))}">دانلود ⬇</a>`;}if(m.kind==='gif')body+=`<div class="media-card"><img src="${esc(backendUrl(m.file_url))}"><a class="download-btn" download href="${esc(backendUrl('/api/media/download/'+m.id))}">دانلود GIF ⬇</a></div>`;if(m.kind==='sticker')body+=`<div class="media-card"><img src="${esc(backendUrl(m.file_url))}" style="max-width:180px;max-height:180px"><a class="download-btn" download href="${esc(backendUrl('/api/media/download/'+m.id))}">ذخیره استیکر ⬇</a></div>`;if(Array.isArray(m.quote_ids)&&m.quote_ids.length)body+=`<div class="quote-block">💬 نقل قول ${m.quote_ids.length} پیام</div>`;if(m.text&&!/^\[\[ZENTO_(ARTICLE|POLL|LOCATION)\]\]/.test(m.text))body+=`<div class="body-text">${m.bot_id?formatBotText(m.text):formatText(m.text)}</div>`;if(m.expires_at)body+=`<small class="expiry-note">⏱️ ناپدیدشونده</small>`;body+=renderBotMarkup(m.reply_markup,m.id);const actions=`<div class="msg-actions"><button data-act="reply">↩ پاسخ</button><button data-act="select">☑ انتخاب</button><button data-act="link">🔗 لینک</button><button data-act="forward">↪ فوروارد</button><button data-act="save">🔖 ذخیره</button>${mine?'<button data-act="delete">🗑 حذف</button>':''}<button data-act="react">❤️</button></div>`;row.innerHTML=`${!mine?avatar({display_name:sender,avatar:m.avatar},'avatar mini-avatar'):''}<div class="bubble"><div class="meta">${!mine?`<button class="sender-name">${esc(sender)}</button>`:''}<span>${new Date(m.created_at).toLocaleTimeString('fa-IR',{hour:'2-digit',minute:'2-digit'})}</span>${mine?`<span class="msg-status">✓</span>`:''}</div>${body}${actions}<div class="reactions"></div></div>`;$('messages').appendChild(row);messageCache[m.id]=m;renderReactions(row,m.reactions);bindMessageRow(row);bindMessageContext(row);bindCustomMediaTriggers(row);bindInlineAudioPlayers(row);renderBotCommandLinks(row);refreshBotCommandsPanel();row.querySelectorAll('.poll-choice').forEach(b=>b.onclick=()=>{row.querySelectorAll('.poll-choice').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');b.querySelector('span').textContent='●'});row.querySelector('.message-location')?.addEventListener('click',()=>openCustomMedia('location',`https://www.openstreetmap.org/?mlat=${row.querySelector('.message-location').dataset.lat}&mlon=${row.querySelector('.message-location').dataset.lon}#map=16/${row.querySelector('.message-location').dataset.lat}/${row.querySelector('.message-location').dataset.lon}`,'موقعیت مکانی'));}
function mediaAudio(url,voice,name,id){const u=backendUrl(url);const label=voice?'پیام صوتی':name||'آهنگ';return `<div class="inline-audio-player ${voice?'voice':'song'}" data-audio-url="${esc(u)}"><audio preload="metadata" src="${esc(u)}"></audio><button type="button" class="inline-audio-play" aria-label="پخش">▶</button><div class="inline-audio-main"><div class="inline-audio-title"><b>${esc(label)}</b><span class="inline-audio-time">0:00 / 0:00</span></div><input class="inline-audio-seek" type="range" min="0" max="100" value="0" step="0.1"><div class="inline-audio-bottom"><button type="button" class="inline-audio-speed">1×</button><button type="button" class="inline-audio-mute">🔊</button></div></div><a class="inline-audio-download" download href="${esc(backendUrl('/api/media/download/'+id))}" title="دانلود">⬇</a></div>`}
function removeMessageContextMenu(){document.getElementById('messageContextMenu')?.remove()}
function messageCopyText(m){const text=(m?.text||'').replace(/^\[\[ZENTO_[^\]]+\]\]/,'').trim();return text||m?.file_name||''}
async function copyMessageImage(m){try{const url=backendUrl(m.file_url);const r=await fetch(url);const blob=await r.blob();if(navigator.clipboard?.write&&window.ClipboardItem){await navigator.clipboard.write([new ClipboardItem({[blob.type]:blob})]);showToast('تصویر کپی شد');}else{await navigator.clipboard.writeText(url);showToast('لینک تصویر کپی شد')} }catch{try{await navigator.clipboard.writeText(backendUrl(m.file_url));showToast('لینک تصویر کپی شد')}catch{showToast('کپی تصویر انجام نشد',true)}}}
function showMessageContextMenu(row,x,y){removeMessageContextMenu();const m=messageCache[row.dataset.msg]||{};const hasImage=!!m.file_url&&String(m.file_type||'').startsWith('image/');const hasText=!!messageCopyText(m);const menu=document.createElement('div');menu.id='messageContextMenu';menu.className='message-context-menu';menu.innerHTML=`<div class="quick-reactions"><button data-act="react" data-e="❤️">❤️</button><button data-act="react" data-e="👍">👍</button><button data-act="react" data-e="😂">😂</button><button data-act="react" data-e="🔥">🔥</button><button data-act="react" data-e="👏">👏</button></div><div class="menu-sep"></div><button data-act="reply"><span>↩</span><span>پاسخ</span></button>${hasText?'<button data-act="copyText"><span>⧉</span><span>کپی متن</span></button>':''}${hasImage?'<button data-act="copyImage"><span>▧</span><span>کپی تصویر</span></button>':''}<button data-act="save"><span>🔖</span><span>ذخیره</span></button><button data-act="forward"><span>↗</span><span>فوروارد</span></button><button data-act="select"><span>☑</span><span>انتخاب</span></button><button data-act="delete" class="danger"><span>⌫</span><span>حذف برای من</span></button>${Number(m.sender_id)===Number(me?.id)?'<button data-act="deleteAll" class="danger"><span>✦</span><span>حذف برای همه</span></button>':''}`;document.body.appendChild(menu);const r=menu.getBoundingClientRect();menu.style.left=Math.max(8,Math.min(x||20,innerWidth-r.width-8))+'px';menu.style.top=Math.max(8,Math.min(y||20,innerHeight-r.height-8))+'px';menu.querySelectorAll('[data-act]').forEach(b=>b.onclick=async()=>{const a=b.dataset.act;try{if(a==='copyText'){await navigator.clipboard.writeText(messageCopyText(m));showToast('متن کپی شد')}else if(a==='copyImage'){await copyMessageImage(m)}else if(a==='reply'){row.querySelector('[data-act="reply"]')?.click()}else if(a==='save'){row.querySelector('[data-act="save"]')?.click()}else if(a==='forward'){row.querySelector('[data-act="forward"]')?.click()}else if(a==='select'){row.querySelector('[data-act="select"]')?.click()}else if(a==='delete'){row.querySelector('[data-act="delete"]')?.click()}else if(a==='deleteAll'){row.querySelector('[data-act="deleteAll"]')?.click()}else if(a==='react'){if(socket?.connected)socket.emit('react',{messageId:Number(row.dataset.msg),emoji:b.dataset.e})} }catch(e){showToast(e.message||'عملیات ناموفق بود',true)}removeMessageContextMenu()});setTimeout(()=>{const close=e=>{if(!menu.contains(e.target)){removeMessageContextMenu();document.removeEventListener('pointerdown',close)}};document.addEventListener('pointerdown',close)},0)}
function bindMessageContext(row){row.addEventListener('contextmenu',e=>{e.preventDefault();showMessageContextMenu(row,e.clientX,e.clientY)});let timer=null;row.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse')return;timer=setTimeout(()=>showMessageContextMenu(row,e.clientX||innerWidth/2,e.clientY||innerHeight/2),520)});['pointerup','pointercancel','pointerleave'].forEach(ev=>row.addEventListener(ev,()=>{if(timer){clearTimeout(timer);timer=null}}))}
function bindMessageRow(row){row.querySelector('[data-act="reply"]')?.addEventListener('click',()=>{const mId=Number(row.dataset.msg);replyTo=mId;$('replyPreview').textContent=row.querySelector('.body-text')?.textContent||'پیام چندرسانه‌ای';$('replyBar').classList.remove('hidden');$('text').focus()});row.querySelector('[data-act="save"]')?.addEventListener('click',async()=>{try{const r=await api('/api/saved/'+row.dataset.msg,{method:'POST'});showToast(r.saved?'پیام ذخیره شد':'از ذخیره‌شده‌ها حذف شد')}catch(e){showToast(e.message,true)}});row.querySelector('[data-act="delete"]')?.addEventListener('click',()=>{if(socket?.connected)socket.emit('delete_message',{id:Number(row.dataset.msg),mode:'for_me'})});
row.querySelector('[data-act="deleteAll"]')?.addEventListener('click',()=>{if(!confirm('این پیام برای همه کاربران حذف شود؟ این عملیات قابل بازگشت نیست.'))return;if(socket?.connected)socket.emit('delete_message',{id:Number(row.dataset.msg),mode:'for_everyone'})});row.querySelector('[data-act="link"]')?.addEventListener('click',async()=>{try{const r=await api('/api/messages/'+row.dataset.msg+'/link');await navigator.clipboard.writeText(r.url);showToast('لینک پیام کپی شد')}catch(e){showToast(e.message,true)}});
row.querySelector('[data-act="forward"]')?.addEventListener('click',async()=>{const cid=prompt('شناسه گفتگو مقصد را وارد کنید:');if(!cid)return;try{await api('/api/messages/'+row.dataset.msg+'/forward',{method:'POST',body:JSON.stringify({conversationId:Number(cid)})});showToast('پیام فوروارد شد')}catch(e){showToast(e.message,true)}});
row.querySelector('[data-act="select"]')?.addEventListener('click',()=>{row.classList.toggle('selected');selectedStage2Messages??=[];const id=Number(row.dataset.msg);selectedStage2Messages=selectedStage2Messages.includes(id)?selectedStage2Messages.filter(x=>x!==id):[...selectedStage2Messages,id];showToast(`تعداد انتخاب: ${selectedStage2Messages.length}`)});
row.querySelector('[data-act="react"]')?.addEventListener('click',()=>{const em=promptEmoji();if(em)socket.emit('react',{messageId:Number(row.dataset.msg),emoji:em})});row.querySelector('.sender-name')?.addEventListener('click',()=>{const m=messageCache[Number(row.dataset.msg)];if(m?.sender_id)openUserProfile(m.sender_id)});row.querySelector('.mini-avatar')?.addEventListener('click',()=>{const m=messageCache[Number(row.dataset.msg)];if(m?.sender_id)openUserProfile(m.sender_id)});bindCustomMediaTriggers(row)}
const messageCache=new Proxy({},{});function promptEmoji(){return '❤️'}function renderReactions(row,reactions={}){const r=row.querySelector('.reactions');r.innerHTML=Object.entries(reactions||{}).map(([e,a])=>`<button class="reaction">${e} ${a.length}</button>`).join('')}
function scrollBottom(){const m=$('messages');m.scrollTop=m.scrollHeight}
$('composer').onsubmit=async e=>{e.preventDefault();if(!current)return;const text=$('text').value.trim();if(!text)return;try{const out=await api('/api/messages',{method:'POST',body:JSON.stringify({conversationId:current.id,text,replyTo})});$('text').value='';messageSendTone();replyTo=null;selectedStage2Messages=[];document.querySelectorAll('.bubble-row.selected').forEach(x=>x.classList.remove('selected'));$('replyBar').classList.add('hidden');appendMessage(out);scrollBottom();if(socket?.connected)socket.emit('typing',{conversationId:current.id,typing:false})}catch(err){showToast(err.message,true)}};
$('text').oninput=()=>{if(!current||!socket?.connected)return;socket.emit('typing',{conversationId:current.id,typing:true});clearTimeout(window.tt);window.tt=setTimeout(()=>socket.emit('typing',{conversationId:current.id,typing:false}),900)};
$('cancelReply').onclick=()=>{replyTo=null;$('replyBar').classList.add('hidden')};
function closeAttachMenu(){document.getElementById('attachMenu')?.remove()}
function openAttachMenu(){if(!current)return;closeAttachMenu();const m=document.createElement('div');m.id='attachMenu';m.className='attach-popover';m.innerHTML=`<button class="attach-choice" data-attach="media"><span>🖼️</span><b>عکس یا ویدیو</b><small>گالری</small></button><button class="attach-choice" data-attach="document"><span>📄</span><b>سند</b><small>فایل و PDF</small></button><button class="attach-choice" data-attach="poll"><span>📊</span><b>نظرسنجی</b><small>سؤال و گزینه‌ها</small></button><button class="attach-choice" data-attach="article"><span>📰</span><b>مقاله</b><small>متن طولانی</small></button><button class="attach-choice" data-attach="location"><span>📍</span><b>موقعیت</b><small>مکان فعلی</small></button><button class="attach-choice" data-attach="music"><span>🎵</span><b>موسیقی</b><small>آهنگ</small></button>`;document.body.appendChild(m);const r=$('attach').getBoundingClientRect();const w=300;let left=Math.min(Math.max(8,r.left),innerWidth-w-8);m.style.left=left+'px';m.style.bottom=(innerHeight-r.top+8)+'px';m.querySelectorAll('[data-attach]').forEach(b=>b.onclick=()=>handleAttachChoice(b.dataset.attach));setTimeout(()=>document.addEventListener('pointerdown',onAttachOutside,{once:true}),0)}
function onAttachOutside(e){if(!e.target.closest('#attachMenu')&&!e.target.closest('#attach'))closeAttachMenu()}
function openStructuredComposer(kind){const modal=$('attachComposerModal');const body=$('attachComposerBody');$('attachComposerKind').textContent=kind==='article'?'مقاله پیشرفته':kind==='poll'?'نظرسنجی':'موقعیت مکانی';$('attachComposerTitle').textContent=kind==='article'?'نوشتن مقاله':kind==='poll'?'ساخت نظرسنجی':'ارسال موقعیت';if(kind==='article')body.innerHTML=`<div class="article-editor"><input id="articleTitle" placeholder="عنوان مقاله" maxlength=140><div class="article-toolbar"><button data-cmd="bold">B</button><button data-cmd="italic">I</button><button data-cmd="underline">U</button><button data-cmd="insertUnorderedList">• لیست</button><button data-cmd="formatBlock" data-val="blockquote">❝ نقل‌قول</button></div><div id="articleBody" class="article-content" contenteditable="true" data-placeholder="متن مقاله را حرفه‌ای بنویس…"></div></div>`;else if(kind==='poll')body.innerHTML=`<div class="poll-editor"><input id="pollQuestion" placeholder="سؤال نظرسنجی" maxlength=240><div id="pollOptions"></div><button id="addPollOption" class="secondary">＋ افزودن گزینه</button><label class="poll-single"><input id="pollSingle" type="checkbox" checked> هر کاربر فقط یک گزینه انتخاب کند</label></div>`;else body.innerHTML=`<div class="location-editor"><div class="location-preview">📍</div><b>موقعیت مکانی شما</b><span id="locationStatus">در حال دریافت موقعیت…</span><div id="locationMap" class="location-map"></div></div>`;modal.classList.remove('hidden');modal.setAttribute('aria-hidden','false');$('attachComposerSend').textContent='ارسال';if(kind==='article'){document.querySelectorAll('.article-toolbar button').forEach(b=>b.onclick=()=>document.execCommand(b.dataset.cmd,false,b.dataset.val||null))}if(kind==='poll'){const add=()=>{const row=document.createElement('div');row.className='poll-option-input';row.innerHTML=`<input placeholder="گزینه ${document.querySelectorAll('.poll-option-input').length+1}" maxlength=100><button type="button">×</button>`;row.querySelector('button').onclick=()=>row.remove();$('pollOptions').appendChild(row)};for(let i=0;i<2;i++)add();$('addPollOption').onclick=add}if(kind==='location'){if(!navigator.geolocation){$('locationStatus').textContent='مرورگر موقعیت را پشتیبانی نمی‌کند';return}navigator.geolocation.getCurrentPosition(p=>{const lat=p.coords.latitude.toFixed(6),lon=p.coords.longitude.toFixed(6);$('locationStatus').textContent=`${lat}, ${lon}`;$('locationMap').innerHTML=`<iframe title="نقشه موقعیت" src="https://www.openstreetmap.org/export/embed.html?bbox=${lon-0.01}%2C${lat-0.01}%2C${Number(lon)+0.01}%2C${Number(lat)+0.01}&layer=mapnik&marker=${lat}%2C${lon}"></iframe>`;modal.dataset.lat=lat;modal.dataset.lon=lon},()=>{$('locationStatus').textContent='دسترسی به موقعیت داده نشد'}, {enableHighAccuracy:true,timeout:10000})}}
async function handleAttachChoice(type){closeAttachMenu();if(type==='media'){ $('file').accept='image/*,video/*';$('file').multiple=true;$('file').click();return}if(type==='document'){ $('file').accept='.pdf,.doc,.docx,.txt,.zip,.rar,application/pdf,text/plain,application/msword,application/vnd.openxmlformats-officedocument.wordprocessingml.document,application/zip';$('file').multiple=true;$('file').click();return}if(type==='music'){ $('file').accept='audio/*,.mp3,.wav,.m4a,.ogg';$('file').multiple=true;$('file').click();return}if(['article','poll','location'].includes(type)){openStructuredComposer(type);return}}
async function sendStructuredComposer(){const modal=$('attachComposerModal');const kind=$('attachComposerKind').textContent;if(kind==='مقاله پیشرفته'){const title=$('articleTitle')?.value.trim();const body=$('articleBody')?.innerText.trim();if(!title||!body)return showToast('عنوان و متن مقاله را کامل کن',true);return sendStructuredText('[[ZENTO_ARTICLE]]'+JSON.stringify({title,body}))}if(kind==='نظرسنجی'){const question=$('pollQuestion')?.value.trim();const options=[...document.querySelectorAll('.poll-option-input input')].map(x=>x.value.trim()).filter(Boolean);if(!question||options.length<2)return showToast('سؤال و حداقل دو گزینه لازم است',true);return sendStructuredText('[[ZENTO_POLL]]'+JSON.stringify({question,options,single:!!$('pollSingle')?.checked}))}if(kind==='موقعیت مکانی'){const lat=modal.dataset.lat,lon=modal.dataset.lon;if(!lat)return showToast('موقعیت دریافت نشده',true);return sendStructuredText('[[ZENTO_LOCATION]]'+JSON.stringify({lat,lon}))}}
async function sendStructuredText(text){try{const out=await api('/api/messages',{method:'POST',body:JSON.stringify({conversationId:current.id,text,replyTo,profileId:stage1ProfileByConv[current.id]||stage1ProfileByConv._default})});replyTo=null;$('replyBar')?.classList.add('hidden');appendMessage(out);scrollBottom()}catch(e){showToast(e.message,true)}}
$('attach').onclick=openAttachMenu;
let pendingAttachments=[];
function closeAttachComposer(){const m=$('attachComposerModal');if(m){m.classList.add('hidden');m.setAttribute('aria-hidden','true')}pendingAttachments.forEach(x=>{try{URL.revokeObjectURL(x.url)}catch{}});pendingAttachments=[]}
function attachmentKind(f){if(f.type==='image/gif')return'gif';if(f.type.startsWith('image/'))return'image';if(f.type.startsWith('video/'))return'video';if(f.type.startsWith('audio/'))return'audio';return'file'}
function makeAttachmentEditorShell(){
  if($('mediaEditModal'))return;
  const d=document.createElement('div');d.id='mediaEditModal';d.className='custom-media-modal hidden';d.innerHTML=`<div class="custom-media-shell media-edit-shell"><div class="custom-media-top"><div><span id="mediaEditKind">ویرایش رسانه</span><b id="mediaEditTitle">ویرایش</b></div><button id="mediaEditClose" class="custom-media-close">×</button></div><div id="mediaEditBody" class="media-edit-body"></div><div class="media-edit-footer"><div class="media-edit-tools" id="mediaEditTools"></div><div class="media-edit-caption"><label>کپشن</label><textarea id="mediaEditCaption" maxlength="2000" placeholder="برای این رسانه کپشن بنویس…"></textarea></div><div class="media-edit-actions"><button id="mediaEditCancel" class="secondary">لغو</button><button id="mediaEditApply" class="primary">اعمال تغییرات</button></div></div></div>`;document.body.appendChild(d);
  $('mediaEditClose').onclick=closeMediaEditor;$('mediaEditCancel').onclick=closeMediaEditor;$('mediaEditApply').onclick=applyMediaEditor;
}
let editingAttachmentIndex=-1,mediaEditorState=null;
function closeMediaEditor(){const m=$('mediaEditModal');if(m)m.classList.add('hidden');mediaEditorState=null;editingAttachmentIndex=-1}
function openMediaEditor(i){makeAttachmentEditorShell();const x=pendingAttachments[i];if(!x||!['image','gif','video'].includes(x.kind))return;editingAttachmentIndex=i;const m=$('mediaEditModal'),body=$('mediaEditBody'),tools=$('mediaEditTools');$('mediaEditTitle').textContent=x.kind==='video'?'ویرایش ویدیو':'ویرایش عکس';$('mediaEditCaption').value=x.caption||'';m.classList.remove('hidden');mediaEditorState={kind:x.kind,filter:'none',draw:false,strokes:[],text:'',start:0,end:0,videoDuration:0};tools.innerHTML=x.kind==='video'?`<button data-edit="trim">✂️ کوتاه کردن</button><button data-edit="caption">📝 کپشن</button>`:`<button data-edit="filter">🎨 فیلتر</button><button data-edit="draw">✏️ خط‌خطی</button><button data-edit="text">T متن</button><button data-edit="caption">📝 کپشن</button>`;
  if(x.kind==='video'){body.innerHTML=`<div class="media-edit-stage"><video id="editVideo" src="${x.url}" controls playsinline></video></div><div class="trim-panel"><label>شروع <output id="trimStartOut">0:00</output><input id="trimStart" type="range" min="0" max="1" step="0.1" value="0"></label><label>پایان <output id="trimEndOut">0:00</output><input id="trimEnd" type="range" min="0" max="1" step="0.1" value="1"></label><small>برای جلوگیری از افت کیفیت، خروجی ویدیو در قالب WebM تولید می‌شود.</small></div>`;const v=$('editVideo');v.onloadedmetadata=()=>{mediaEditorState.videoDuration=v.duration;$('trimStart').max=v.duration;$('trimEnd').max=v.duration;$('trimEnd').value=v.duration;$('trimEndOut').textContent=fmtMediaTime(v.duration)};$('trimStart').oninput=e=>{const a=Number(e.target.value),b=Number($('trimEnd').value);if(a>b-0.1)e.target.value=Math.max(0,b-0.1);mediaEditorState.start=Number(e.target.value);$('trimStartOut').textContent=fmtMediaTime(mediaEditorState.start)};$('trimEnd').oninput=e=>{const b=Number(e.target.value),a=Number($('trimStart').value);if(b<a+0.1)e.target.value=Math.min(mediaEditorState.videoDuration,a+0.1);mediaEditorState.end=Number(e.target.value);$('trimEndOut').textContent=fmtMediaTime(mediaEditorState.end)};
  }else{body.innerHTML=`<div class="media-edit-stage image-edit-stage"><canvas id="editCanvas"></canvas><div class="edit-hint">برای نوشتن متن از ابزار T و برای نقاشی روی تصویر بکش.</div></div>`;initImageEditor(x)}
  tools.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>handleMediaEditTool(b.dataset.edit));
}
function initImageEditor(x){const img=new Image();img.onload=()=>{const c=$('editCanvas'),max=900,scale=Math.min(1,max/img.width);c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);const ctx=c.getContext('2d');ctx.drawImage(img,0,0,c.width,c.height);mediaEditorState.image=img;mediaEditorState.scale=scale;mediaEditorState.canvas=c;bindCanvasDrawing(c)};img.src=x.url}
function bindCanvasDrawing(c){c.onpointerdown=e=>{if(!mediaEditorState.draw)return;mediaEditorState.strokes.push([{x:e.offsetX,y:e.offsetY}]);c.setPointerCapture(e.pointerId)};c.onpointermove=e=>{if(!mediaEditorState.draw||!mediaEditorState.strokes.length)return;const st=mediaEditorState.strokes[mediaEditorState.strokes.length-1];st.push({x:e.offsetX,y:e.offsetY});redrawImageCanvas()};c.onpointerup=()=>{};c.ondblclick=()=>{if(mediaEditorState.text){redrawImageCanvas();mediaEditorState.text=''}}}
function redrawImageCanvas(){const st=mediaEditorState, c=st.canvas,ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height);ctx.save();ctx.filter=st.filter||'none';ctx.drawImage(st.image,0,0,c.width,c.height);ctx.restore();ctx.lineWidth=5;ctx.lineCap='round';ctx.strokeStyle='#ff2d75';for(const pts of st.strokes||[]){ctx.beginPath();pts.forEach((pt,j)=>j?ctx.lineTo(pt.x,pt.y):ctx.moveTo(pt.x,pt.y));ctx.stroke()}if(st.text){ctx.font='bold 34px sans-serif';ctx.textAlign='center';ctx.fillStyle='#fff';ctx.strokeStyle='rgba(0,0,0,.75)';ctx.lineWidth=5;ctx.strokeText(st.text,c.width/2,c.height-35);ctx.fillText(st.text,c.width/2,c.height-35)}}
function handleMediaEditTool(tool){const st=mediaEditorState;if(!st)return;if(tool==='filter'){const filters=['none','grayscale(1)','sepia(.8)','contrast(1.35) saturate(1.3)','brightness(1.15) saturate(1.4)','blur(1px)'];st.filter=filters[(filters.indexOf(st.filter)+1)%filters.length];redrawImageCanvas();showToast('فیلتر: '+st.filter)}else if(tool==='draw'){st.draw=!st.draw;showToast(st.draw?'حالت خط‌خطی فعال شد':'حالت خط‌خطی خاموش شد')}else if(tool==='text'){let box=document.querySelector('.media-inline-text-tool');if(!box){box=document.createElement('div');box.className='media-inline-text-tool';box.innerHTML='<input id=\"mediaOverlayText\" maxlength=120 placeholder=\"متن روی عکس…\"><button type=\"button\" id=\"mediaOverlayApply\">اعمال متن</button>';document.querySelector('.media-edit-body').appendChild(box);box.querySelector('#mediaOverlayApply').onclick=()=>{st.text=box.querySelector('#mediaOverlayText').value.trim();redrawImageCanvas()}}box.querySelector('#mediaOverlayText').focus()}else if(tool==='caption')$('mediaEditCaption').focus();else if(tool==='trim'){$('trimStart')?.focus()}}
async function applyMediaEditor(){const x=pendingAttachments[editingAttachmentIndex];if(!x)return; x.caption=$('mediaEditCaption').value.trim();if(x.kind==='image'||x.kind==='gif'){const c=mediaEditorState.canvas;c.toBlob(blob=>{if(blob){x.file=new File([blob],x.file.name.replace(/\.[^.]+$/i,'.jpg'),{type:'image/jpeg'});x.kind='image';x.url=URL.createObjectURL(x.file)}renderAttachmentPreview();closeMediaEditor()},'image/jpeg',.92);return}if(x.kind==='video'){const v=$('editVideo'),start=Number($('trimStart').value),end=Number($('trimEnd').value);if(start<=0.01&&end>=mediaEditorState.videoDuration-0.01){renderAttachmentPreview();closeMediaEditor();return}try{showToast('در حال آماده‌سازی ویدیو…');const blob=await trimVideo(v,start,end);x.file=new File([blob],x.file.name.replace(/\.[^.]+$/i,'.webm'),{type:'video/webm'});try{URL.revokeObjectURL(x.url)}catch{}x.url=URL.createObjectURL(x.file);renderAttachmentPreview();closeMediaEditor()}catch(e){showToast(e.message||'کوتاه کردن ویدیو ناموفق بود',true)}}}
function trimVideo(video,start,end){return new Promise(async(resolve,reject)=>{try{const stream=video.captureStream?.();if(!stream)throw Error('مرورگر برای ویرایش ویدیو پشتیبانی کافی ندارد');const canvas=document.createElement('canvas');canvas.width=video.videoWidth;canvas.height=video.videoHeight;const ctx=canvas.getContext('2d');const out=canvas.captureStream(30);stream.getAudioTracks().forEach(t=>out.addTrack(t));const mime=MediaRecorder.isTypeSupported('video/webm;codecs=vp9,opus')?'video/webm;codecs=vp9,opus':'video/webm';const rec=new MediaRecorder(out,{mimeType:mime});const chunks=[];rec.ondataavailable=e=>e.data.size&&chunks.push(e.data);rec.onerror=()=>reject(Error('تولید ویدیو ناموفق بود'));rec.onstop=()=>resolve(new Blob(chunks,{type:mime}));video.currentTime=start;await new Promise(r=>video.onseeked=r);rec.start(100);await video.play();let raf=0;const draw=()=>{if(video.currentTime>=end){cancelAnimationFrame(raf);video.pause();rec.stop();out.getTracks().forEach(t=>t.stop());return}ctx.drawImage(video,0,0,canvas.width,canvas.height);raf=requestAnimationFrame(draw)};draw()}catch(e){reject(e)}})}
function renderAttachmentPreview(){const body=$('attachComposerBody');if(!body)return;body.innerHTML='';if(!pendingAttachments.length){body.innerHTML='<div class="empty">رسانه‌ای انتخاب نشده</div>';return}const grid=document.createElement('div');grid.className='attachment-preview-grid';pendingAttachments.forEach((x,i)=>{const card=document.createElement('div');card.className='attachment-preview-item';let media='';if(x.kind==='image'||x.kind==='gif')media=`<img src="${x.url}" alt="">`;else if(x.kind==='video')media=`<video src="${x.url}" controls playsinline></video>`;else if(x.kind==='audio')media=`<div class="attachment-audio-preview">🎵<span>${esc(x.file.name)}</span><audio src="${x.url}" controls></audio></div>`;else media=`<div class="attachment-doc-preview">📄<b>${esc(x.file.name)}</b><small>${Math.ceil(x.file.size/1024)} KB</small></div>`;const edit=['image','gif','video'].includes(x.kind)?`<button class="attachment-edit" data-edit-i="${i}">✏️ ویرایش</button>`:'';card.innerHTML=media+edit+`<button class="attachment-remove" data-i="${i}">×</button>${x.caption?`<div class="attachment-caption-preview">${esc(x.caption)}</div>`:''}`;grid.appendChild(card)});body.appendChild(grid);$('attachComposerTitle').textContent=`پیش‌نمایش ${pendingAttachments.length} فایل`;grid.querySelectorAll('.attachment-remove').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.i);try{URL.revokeObjectURL(pendingAttachments[i].url)}catch{}pendingAttachments.splice(i,1);renderAttachmentPreview()});grid.querySelectorAll('.attachment-edit').forEach(b=>b.onclick=()=>openMediaEditor(Number(b.dataset.editI)))}
function openAttachmentComposer(files){makeAttachmentEditorShell();pendingAttachments=Array.from(files).slice(0,30).map(file=>({file,kind:attachmentKind(file),url:URL.createObjectURL(file),caption:''}));const m=$('attachComposerModal');m.classList.remove('hidden');m.setAttribute('aria-hidden','false');renderAttachmentPreview()}
async function uploadPendingAttachments(){if(!current||!pendingAttachments.length)return;const list=[...pendingAttachments];for(const x of list){const fd=new FormData();fd.append('file',x.file,x.file.name);const u=await api('/api/upload',{method:'POST',body:fd});const out=await api('/api/messages',{method:'POST',body:JSON.stringify({conversationId:current.id,text:x.caption||'',fileUrl:u.url,fileType:u.mime,fileName:u.name,kind:x.kind,profileId:stage1ProfileByConv[current.id]||stage1ProfileByConv._default})});appendMessage(out)}scrollBottom();closeAttachComposer();$('file').value=''}
$('file').onchange=()=>{const files=$('file').files;if(files?.length)openAttachmentComposer(files)};
$('attachComposerClose').onclick=closeAttachComposer;$('attachComposerCancel').onclick=closeAttachComposer;$('attachComposerSend').onclick=async()=>{try{$('attachComposerSend').disabled=true;if(pendingAttachments.length)await uploadPendingAttachments();else{await sendStructuredComposer();closeAttachComposer();}}catch(e){showToast(e.message,true)}finally{$('attachComposerSend').disabled=false}};

let messageRecorder=null;
let messageRecorderStream=null;
let messageRecorderChunks=[];
let messageRecorderMode='voice';
let messageRecorderStartedAt=0;
let messageRecorderPausedAt=0;
let messageRecorderPausedTotal=0;
let messageRecorderTimer=null;
let messageRecorderSending=false;
let messageRecorderPreviewUrl=null;
let messageRecorderPreviewKind=null;
let messageRecorderPreviewMedia=null;
function formatRecordTime(sec){sec=Math.max(0,Math.floor(sec));return `${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`}
function updateRecordTimer(){
  const elapsed=(messageRecorderPausedAt?messageRecorderPausedAt:Date.now())-messageRecorderStartedAt-messageRecorderPausedTotal;
  const txt=formatRecordTime(elapsed/1000);
  $('recordingTimer').textContent=txt;$('recordingSecondsText').textContent=txt;
}
function cleanupRecorderPreview(){const rv=$('recordingPreview');if(rv){try{rv.pause()}catch{}rv.src='';rv.controls=false}if(messageRecorderPreviewMedia){try{messageRecorderPreviewMedia.pause()}catch{}}if(messageRecorderPreviewUrl){URL.revokeObjectURL(messageRecorderPreviewUrl);messageRecorderPreviewUrl=null}messageRecorderPreviewKind=null;messageRecorderPreviewMedia=null;const p=$('recordingPlay');if(p){p.disabled=true;p.textContent='▶ پخش'}$('recordingAudioPreview')?.classList.add('hidden');$('recordingPreviewStatus')&&( $('recordingPreviewStatus').textContent='برای گوش دادن روی پخش بزن')}
function closeRecordingPanel(){
  clearInterval(messageRecorderTimer);messageRecorderTimer=null;
  $('recordingPanel')?.classList.add('hidden');$('recordingPanel')?.classList.remove('paused');$('recordingPanel')?.setAttribute('aria-hidden','true');
  if($('recordingPreview')){$('recordingPreview').srcObject=null}
  cleanupRecorderPreview();
}
function resetMessageRecorder(){
  clearInterval(messageRecorderTimer);messageRecorderTimer=null;
  messageRecorder=null;messageRecorderChunks=[];messageRecorderStartedAt=0;messageRecorderPausedAt=0;messageRecorderPausedTotal=0;messageRecorderSending=false;
  if(messageRecorderStream){messageRecorderStream.getTracks().forEach(t=>t.stop());messageRecorderStream=null}
  closeRecordingPanel();
}
function cancelMessageRecording(){
  try{if(messageRecorder&&messageRecorder.state!=='inactive')messageRecorder.stop()}catch{}
  resetMessageRecorder();showToast('ضبط پیام لغو شد');
}
async function prepareRecordingPreview(){
  if(!messageRecorder||messageRecorderSending||!messageRecorderChunks.length)return false;
  try{
    if(messageRecorder.state==='paused'&&messageRecorder.requestData){messageRecorder.requestData();await new Promise(r=>setTimeout(r,120));}
    const mime=messageRecorder.mimeType||(messageRecorderMode==='video'?'video/webm':'audio/webm');
    const blob=new Blob(messageRecorderChunks,{type:mime});
    if(!blob.size)return false;
    cleanupRecorderPreview();
    messageRecorderPreviewUrl=URL.createObjectURL(blob);messageRecorderPreviewKind=messageRecorderMode;
    const p=$('recordingPlay');p.disabled=false;p.textContent='▶ پخش';$('recordingAudioPreview')?.classList.remove('hidden');$('recordingPreviewStatus').textContent='ضبط آماده پیش‌نمایش است';
    return true;
  }catch{return false}
}
function toggleRecordingPreview(){
  if(!messageRecorderPreviewUrl)return;
  if(messageRecorderPreviewKind==='video'){const v=$('recordingPreview');if(v.src===messageRecorderPreviewUrl&&!v.paused){v.pause();$('recordingPlay').textContent='▶ پخش';$('recordingPreviewStatus').textContent='پیش‌نمایش متوقف شد';return}if(v.srcObject)v.srcObject=null;v.src=messageRecorderPreviewUrl;v.controls=true;v.muted=false;if(v.currentTime>=v.duration||!Number.isFinite(v.duration))v.currentTime=0;v.play().catch(()=>{});$('recordingPreviewWrap').classList.remove('hidden');$('recordingPlay').textContent='⏹ توقف پیش‌نمایش';$('recordingPreviewStatus').textContent='در حال پخش پیش‌نمایش'}else{
    if(!messageRecorderPreviewMedia){messageRecorderPreviewMedia=new Audio(messageRecorderPreviewUrl);messageRecorderPreviewMedia.onended=()=>{$('recordingPlay').textContent='▶ پخش';$('recordingPreviewStatus').textContent='پیش‌نمایش تمام شد'}}
    if(messageRecorderPreviewMedia.paused){messageRecorderPreviewMedia.currentTime=0;messageRecorderPreviewMedia.play().catch(()=>{});$('recordingPlay').textContent='⏸ توقف پیش‌نمایش';$('recordingPreviewStatus').textContent='در حال پخش پیش‌نمایش'}else{messageRecorderPreviewMedia.pause();$('recordingPlay').textContent='▶ پخش';$('recordingPreviewStatus').textContent='پیش‌نمایش متوقف شد'}
  }
}

async function sendMessageRecording(){
  if(messageRecorderSending||!messageRecorder)return;
  messageRecorderSending=true;$('recordingSend').disabled=true;$('recordingPause').disabled=true;$('recordingCancel').disabled=true;$('recordingPlay').disabled=true;$('recordingState').textContent='در حال آماده‌سازی…';
  const rec=messageRecorder;
  try{
    if(rec.state!=='inactive'){
      await new Promise(resolve=>{const done=()=>resolve();rec.addEventListener('stop',done,{once:true});try{rec.stop()}catch{resolve()}});
    }
    if(messageRecorderStream){messageRecorderStream.getTracks().forEach(t=>t.stop());messageRecorderStream=null}
    const mime=rec.mimeType|| (messageRecorderMode==='video'?'video/webm':'audio/webm');
    const ext=messageRecorderMode==='video'?'webm':'webm';
    const blob=new Blob(messageRecorderChunks,{type:mime});
    if(!blob.size)throw Error('ضبط خالی است');
    const fd=new FormData();fd.append('file',blob,messageRecorderMode==='video'?`video-message-${Date.now()}.${ext}`:`voice-${Date.now()}.${ext}`);
    $('recordingState').textContent='در حال آپلود…';
    const u=await api('/api/upload',{method:'POST',body:fd});
    const out=await api('/api/messages',{method:'POST',body:JSON.stringify({conversationId:current.id,fileUrl:u.url,fileType:u.mime||mime,fileName:u.name,kind:messageRecorderMode==='video'?'video':'voice'})});
    appendMessage(out);scrollBottom();resetMessageRecorder();
  }catch(e){messageRecorderSending=false;$('recordingSend').disabled=false;$('recordingPause').disabled=false;$('recordingCancel').disabled=false;$('recordingState').textContent='خطا در ارسال';showToast(e.message||'ارسال پیام ناموفق بود',true)}
}
function toggleMessageRecordingPause(){
  if(!messageRecorder||messageRecorderSending)return;
  const panel=$('recordingPanel');
  if(messageRecorder.state==='recording'){
    messageRecorder.pause();messageRecorderPausedAt=Date.now();panel.classList.add('paused');$('recordingPause').textContent='▶ ادامه';$('recordingState').textContent='متوقف شده';clearInterval(messageRecorderTimer);setTimeout(()=>prepareRecordingPreview(),160);
  }else if(messageRecorder.state==='paused'){
    messageRecorderPausedTotal+=Date.now()-messageRecorderPausedAt;messageRecorderPausedAt=0;cleanupRecorderPreview();if(messageRecorderMode==='video'){const v=$('recordingPreview');v.pause();v.controls=false;v.src='';v.srcObject=messageRecorderStream}messageRecorder.resume();panel.classList.remove('paused');$('recordingPause').textContent='⏸ توقف';$('recordingState').textContent='در حال ضبط';messageRecorderTimer=setInterval(updateRecordTimer,250);
  }
}
async function startMessageRecording(mode){
  if(!current)return;
  if(messageRecorder&&messageRecorder.state!=='inactive')return;
  if(!navigator.mediaDevices?.getUserMedia)return showToast('ضبط در این مرورگر پشتیبانی نمی‌شود',true);
  if(mode==='video'&&location.protocol!=='https:'&&location.hostname!=='localhost')return showToast('برای ضبط ویدیو باید سایت با HTTPS باز شود',true);
  try{
    messageRecorderMode=mode;
    const stream=await navigator.mediaDevices.getUserMedia(mode==='video'?{audio:true,video:{facingMode:'user'}}:{audio:true});
    messageRecorderStream=stream;
    const options=mode==='video'?{mimeType:'video/webm;codecs=vp8,opus'}:{mimeType:'audio/webm;codecs=opus'};
    let rec;try{rec=MediaRecorder.isTypeSupported(options.mimeType)?new MediaRecorder(stream,options):new MediaRecorder(stream)}catch{rec=new MediaRecorder(stream)}
    messageRecorder=rec;messageRecorderChunks=[];messageRecorderStartedAt=Date.now();messageRecorderPausedAt=0;messageRecorderPausedTotal=0;messageRecorderSending=false;
    $('recordingTitle').textContent=mode==='video'?'ضبط ویدیو مسیج':'ضبط پیام صوتی';$('recordingState').textContent='در حال ضبط';$('recordingTimer').textContent='00:00';$('recordingSecondsText').textContent='00:00';$('recordingPause').textContent='⏸ توقف';$('recordingPause').disabled=false;$('recordingCancel').disabled=false;$('recordingSend').disabled=false;
    const previewWrap=$('recordingPreviewWrap');const preview=$('recordingPreview');
    if(mode==='video'){previewWrap.classList.remove('hidden');preview.srcObject=stream}else{previewWrap.classList.add('hidden');preview.srcObject=null}
    const panel=$('recordingPanel');panel.classList.remove('hidden','paused');panel.setAttribute('aria-hidden','false');
    rec.ondataavailable=e=>{if(e.data?.size)messageRecorderChunks.push(e.data)};
    rec.onerror=()=>showToast('خطا هنگام ضبط پیام',true);
    rec.onstop=()=>{if(!messageRecorderSending){clearInterval(messageRecorderTimer)}};
    rec.start(250);messageRecorderTimer=setInterval(updateRecordTimer,250);updateRecordTimer();
  }catch(e){resetMessageRecorder();showToast(mode==='video'?'اجازه دسترسی به دوربین یا میکروفون داده نشد':'اجازه دسترسی به میکروفون داده نشد',true)}
}
