function newMenu(){openModal('گفتگوی جدید',`<div class="modal-choice"><button data-choice="direct">👤 گفتگوی خصوصی</button><button data-choice="group">👥 گروه جدید</button><button data-choice="channel">📢 کانال جدید</button></div>`,()=>{});document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{closeModal();b.dataset.choice==='direct'?searchFocus():b.dataset.choice==='group'?newGroup():newChannel()})}
function searchFocus(){$('search').focus();showToast('نام کاربر را جستجو کن و روی آن بزن')}
async function newGroup(){const users=await api('/api/users');openModal('گروه جدید',`<label>نام گروه<input id="newName" placeholder="مثلاً دوستان دانشگاه"></label><label>شناسه عمومی<input id="newUsername" placeholder="my_group"></label><label>توضیحات<input id="newDesc" placeholder="توضیحات اختیاری"></label><div class="pick-users">${users.map(u=>`<label class="pick"><input type="checkbox" value="${u.id}">${esc(u.display_name)} <small>@${esc(u.username)}</small></label>`).join('')}</div>`,async()=>{const members=[...document.querySelectorAll('.pick input:checked')].map(x=>Number(x.value));const c=await api('/api/conversations/group',{method:'POST',body:JSON.stringify({name:$('newName').value,username:$('newUsername').value,description:$('newDesc').value,members})});closeModal();await loadConvs();openConv(c.id)})}
async function newChannel(){openModal('کانال جدید',`<label>نام کانال<input id="newName" placeholder="کانال زنتو"></label><label>شناسه عمومی<input id="newUsername" placeholder="zento_news"></label><label>توضیحات<input id="newDesc" placeholder="توضیحات"></label>`,async()=>{const c=await api('/api/conversations/channel',{method:'POST',body:JSON.stringify({name:$('newName').value,username:$('newUsername').value,description:$('newDesc').value})});closeModal();await loadConvs();openConv(c.id)})}
function openModal(title,body,onOk){$('modalTitle').textContent=title;$('modalBody').innerHTML=body;$('modal').classList.remove('hidden');$('modalOk').onclick=async()=>{try{await onOk()}catch(e){showToast(e.message,true)}};$('modalOk').textContent='تأیید'}function closeModal(){$('modal').classList.add('hidden')}$('modalX').onclick=$('modalCancel').onclick=closeModal;
async function openProfile(){const u=me;$('profileUser').textContent='@'+u.username;$('profileName').value=u.display_name;$('profileUsername').value=u.username||'';$('profileBio').value=u.bio||'';$('profileAvatarBtn').innerHTML=u.avatar?`<img src="${esc(backendUrl(u.avatar))}">`:esc((u.display_name||'گ')[0]);$('profileModal').classList.remove('hidden');await renderMyProfileMedia()}
async function renderMyProfileMedia(){const host=$('profileMediaManager');if(!host)return;host.innerHTML='<div class="profile-media-loading">در حال بارگذاری رسانه‌های پروفایل…</div>';try{const media=await api('/api/profile/media');const photos=media.filter(x=>x.kind==='photo'),songs=media.filter(x=>x.kind==='song');host.innerHTML=`<div class="profile-media-switch"><button class="active" data-my-panel="about">👤 خلاصه</button><button data-my-panel="gallery">🖼️ گالری (${photos.length}/24)</button><button data-my-panel="songs">🎵 آهنگ‌ها (${songs.length}/3)</button></div><div id="myProfileAbout" class="profile-tab-panel"><div class="profile-media-section"><div class="profile-media-head"><div><b>🖼️ گالری پروفایل</b><small>${photos.length}/24 عکس</small></div></div><div class="profile-media-empty">برای مدیریت تصاویر، تب گالری را باز کن.</div></div><div class="profile-media-section"><div class="profile-media-head"><div><b>🎵 آهنگ‌های پروفایل</b><small>${songs.length}/3 آهنگ</small></div></div><div class="profile-media-empty">برای مدیریت آهنگ‌ها، تب آهنگ‌ها را باز کن.</div></div></div><div id="myProfileGallery" class="profile-tab-panel hidden"><div class="profile-media-section"><div class="profile-media-head"><div><b>🖼️ گالری پروفایل</b><small>${photos.length}/24 عکس</small></div><button type="button" id="addProfilePhoto" class="secondary" ${photos.length>=24?'disabled':''}>＋ افزودن عکس</button></div><input id="profilePhotosInput" type="file" accept="image/jpeg,image/png,image/webp,image/gif" multiple hidden><div class="profile-photo-grid">${photos.map(x=>`<div class="profile-photo-tile"><img src="${esc(backendUrl(x.url))}"><button type="button" data-del-photo="${x.id}">×</button></div>`).join('')||'<div class="profile-media-empty">هنوز عکسی اضافه نکرده‌ای.</div>'}</div></div></div><div id="myProfileSongs" class="profile-tab-panel hidden"><div class="profile-media-section"><div class="profile-media-head"><div><b>🎵 آهنگ‌های پروفایل</b><small>${songs.length}/3 آهنگ</small></div><button type="button" id="addProfileSong" class="secondary" ${songs.length>=3?'disabled':''}>＋ افزودن آهنگ</button></div><input id="profileSongInput" type="file" accept="audio/*" hidden><div class="profile-song-list">${songs.map(x=>`<div class="profile-song-row">${mediaAudio(x.url,false,x.name,x.id)}<button type="button" data-del-song="${x.id}">حذف</button></div>`).join('')||'<div class="profile-media-empty">هنوز آهنگی اضافه نکرده‌ای.</div>'}</div></div></div>`;const setPanel=tab=>{document.querySelectorAll('[data-my-panel]').forEach(x=>x.classList.toggle('active',x.dataset.myPanel===tab));$('myProfileAbout').classList.toggle('hidden',tab!=='about');$('myProfileGallery').classList.toggle('hidden',tab!=='gallery');$('myProfileSongs').classList.toggle('hidden',tab!=='songs');if(tab==='songs')bindInlineAudioPlayers($('myProfileSongs'))};host.querySelectorAll('[data-my-panel]').forEach(x=>x.onclick=()=>setPanel(x.dataset.myPanel));$('addProfilePhoto')?.addEventListener('click',()=>$('profilePhotosInput').click());$('profilePhotosInput')?.addEventListener('change',async e=>{const files=[...e.target.files].slice(0,24-photos.length);for(const f of files){const fd=new FormData();fd.append('photo',f);try{await api('/api/profile/photos',{method:'POST',body:fd})}catch(err){showToast(err.message,true);break}}await renderMyProfileMedia();setTimeout(()=>host.querySelector('[data-my-panel="gallery"]')?.click(),0)});$('addProfileSong')?.addEventListener('click',()=>$('profileSongInput').click());$('profileSongInput')?.addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;const fd=new FormData();fd.append('song',f);try{await api('/api/profile/songs',{method:'POST',body:fd});await renderMyProfileMedia();setTimeout(()=>host.querySelector('[data-my-panel="songs"]')?.click(),0)}catch(err){showToast(err.message,true)}});host.querySelectorAll('[data-del-photo]').forEach(b=>b.onclick=async()=>{await api('/api/profile/photos/'+b.dataset.delPhoto,{method:'DELETE'});renderMyProfileMedia()});host.querySelectorAll('[data-del-song]').forEach(b=>b.onclick=async()=>{await api('/api/profile/songs/'+b.dataset.delSong,{method:'DELETE'});renderMyProfileMedia()})}catch(e){host.innerHTML=`<div class="profile-media-empty">${esc(e.message)}</div>`}}
async function openConversationInfo(c){try{const fresh=await api('/api/conversations/'+c.id+'/messages').then(()=>c).catch(()=>c);const link=c.username?`${location.origin}/#/join/${encodeURIComponent(c.username)}`:'';openModal(c.type==='channel'?'اطلاعات کانال':'اطلاعات گروه',`<div class="profile-preview"><div class="avatar huge">${c.type==='channel'?'📢':'👥'}</div><div><b>${esc(c.name)}</b><small>${c.type==='channel'?'کانال':'گروه'} · ${c.members.length} عضو</small></div></div><div class="profile-line"><span>📝</span><div>${esc(c.description||'توضیحی ثبت نشده')}</div></div>${c.username?`<div class="profile-line"><span>🔗</span><div dir="ltr">@${esc(c.username)}<br><small>${esc(link)}</small></div></div>`:''}<div class="profile-actions">${c.username?`<button id="copyConvLink" class="primary">کپی لینک دعوت</button>`:''}</div>`,async()=>{});$('modalOk').classList.add('hidden');$('modalCancel').textContent='بستن';$('copyConvLink')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(link);showToast('لینک کپی شد')}catch{showToast(link)}})}catch(e){showToast(e.message,true)}}
async function openUserProfile(id){try{const u=await api('/api/users/'+id+'/profile');openModal('👤 پروفایل کاربر',`<div class="public-profile-premium"><div class="public-cover"></div><div class="public-profile-head">${u.avatar?`<div class="premium-story-ring"><img src="${esc(backendUrl(u.avatar))}"></div>`:`<div class="premium-story-ring">${esc((u.display_name||'گ')[0])}</div>`}<div><h3>${esc(u.display_name)}</h3><small>@${esc(u.username)}</small><p>${esc(u.bio||'بیویی ثبت نشده')}</p></div></div><div class="premium-profile-stats"><span><b>${u.photos?.length||0}</b><small>عکس</small></span><span><b>${u.songs?.length||0}</b><small>آهنگ</small></span></div><div class="profile-media-switch"><button class="active" data-profile-panel="about">👤 درباره</button><button data-profile-panel="gallery">🖼️ گالری (${u.photos?.length||0}/24)</button><button data-profile-panel="songs">🎵 آهنگ‌ها (${u.songs?.length||0}/3)</button></div><div class="profile-tab-panel" id="basicProfilePanel"><div class="profile-line"><span>📝</span><div>${esc(u.bio||'بیویی ثبت نشده')}</div></div></div><div class="profile-tab-panel hidden" id="basicGalleryPanel">${u.photos?.length?`<div class="profile-public-gallery premium-gallery">${u.photos.map(x=>`<button class="profile-photo-open" data-src="${esc(backendUrl(x.url))}"><img src="${esc(backendUrl(x.url))}" loading="lazy"></button>`).join('')}</div>`:'<div class="empty">گالری خالی است.</div>'}</div><div class="profile-tab-panel hidden" id="basicSongsPanel">${u.songs?.length?u.songs.map(x=>`<div class="profile-public-song">${mediaAudio(x.url,false,x.name,x.id)}</div>`).join(''):'<div class="empty">آهنگی اضافه نشده است.</div>'}</div><div class="profile-actions"><button id="startDirect" class="primary">💬 پیام</button><button id="blockOther" class="danger">${u.blocked?'🔓 رفع بلاک':'🚫 بلاک'}</button></div></div>`,async()=>{});$('modalOk').classList.add('hidden');$('modalCancel').textContent='بستن';bindInlineAudioPlayers($('modalBody'));document.querySelectorAll('#modalBody [data-profile-panel]').forEach(btn=>btn.onclick=()=>{document.querySelectorAll('#modalBody [data-profile-panel]').forEach(x=>x.classList.toggle('active',x===btn));$('basicProfilePanel').classList.toggle('hidden',btn.dataset.profilePanel!=='about');$('basicGalleryPanel').classList.toggle('hidden',btn.dataset.profilePanel!=='gallery');$('basicSongsPanel').classList.toggle('hidden',btn.dataset.profilePanel!=='songs');if(btn.dataset.profilePanel==='songs')bindInlineAudioPlayers($('basicSongsPanel'))});document.querySelectorAll('#modalBody .profile-photo-open').forEach(b=>b.onclick=()=>{$('lightboxImg').src=b.dataset.src;$('lightbox').classList.remove('hidden')});$('startDirect').onclick=async()=>{try{const c=await api('/api/conversations/direct',{method:'POST',body:JSON.stringify({userId:id})});closeModal();await loadConvs();openConv(c.id)}catch(e){showToast(e.message,true)}};$('blockOther').onclick=async()=>{try{const r=await api('/api/users/'+id+'/block',{method:'POST'});$('blockOther').textContent=r.blocked?'🔓 رفع بلاک':'🚫 بلاک';showToast(r.blocked?'کاربر بلاک شد':'بلاک برداشته شد')}catch(e){showToast(e.message,true)}}}catch(e){showToast(e.message,true)}}
async function openSaved(){try{const data=await api('/api/saved/chat');$('savedList').innerHTML='';const personal=data.messages||[];const saved=(data.saved||[]).map(x=>x.message).filter(Boolean);const all=[...personal,...saved].sort((a,b)=>new Date(a.created_at)-new Date(b.created_at));all.forEach(m=>appendSavedMessage(m));$('savedModal').classList.remove('hidden');$('savedSearch').value='';setTimeout(()=>{const x=$('savedList');x.scrollTop=x.scrollHeight},0)}catch(e){showToast(e.message,true)}}
function appendSavedMessage(m){const mine=Number(m.sender_id)===Number(me.id);const row=document.createElement('div');row.className='bubble-row '+(mine?'mine':'');row.dataset.savedMsg=m.id;let body='';if(m.file_url){if(m.file_type?.startsWith('image/'))body+=`<button type="button" class="media-card custom-media-trigger image-message-card" data-media-kind="image" data-media-url="${esc(backendUrl(m.file_url))}" data-media-title="${esc(m.file_name||'تصویر')}"><img src="${esc(backendUrl(m.file_url))}" alt="تصویر"><span class="media-overlay-label">⤢ باز کردن تصویر</span></button><a class="download-btn" download href="${esc(backendUrl('/api/media/download/'+m.id))}">دانلود ⬇</a>`;else if(m.file_type?.startsWith('video/'))body+=`<button type="button" class="media-card custom-media-trigger video-message-card" data-media-kind="video" data-media-url="${esc(backendUrl(m.file_url))}" data-media-title="${esc(m.kind==='video'?'ویدیو مسیج':m.file_name||'ویدیو')}"><span class="video-thumb-placeholder">▶</span><span class="media-overlay-label">▶ پخش</span></button><a class="download-btn" download href="${esc(backendUrl('/api/media/download/'+m.id))}">دانلود ⬇</a>`;else if(m.file_type?.startsWith('audio/')||m.kind==='voice')body+=mediaAudio(m.file_url,m.kind==='voice',m.file_name,m.id);else body+=`<div class="file-card"><span>📎</span><div class="file-name">${esc(m.file_name||'فایل')}</div><a class="download-btn" download href="${esc(backendUrl('/api/media/download/'+m.id))}">دانلود ⬇</a></div>`}if(m.text&&!/^\[\[ZENTO_(ARTICLE|POLL|LOCATION)\]\]/.test(m.text))body+=`<div class="body-text">${formatText(m.text)}</div>`;row.innerHTML=`<div class="bubble"><div class="meta"><span>${new Date(m.created_at).toLocaleTimeString('fa-IR',{hour:'2-digit',minute:'2-digit'})}</span>${mine?`<span class="msg-status">✓</span>`:''}</div>${body}</div>`;$('savedList').appendChild(row);messageCache[m.id]=m;bindMessageContext(row);bindCustomMediaTriggers(row);bindInlineAudioPlayers(row)}
$('closeSaved').onclick=()=>$('savedModal').classList.add('hidden');
$('savedSearch').oninput=()=>{const q=$('savedSearch').value.trim().toLowerCase();document.querySelectorAll('#savedList .bubble-row').forEach(row=>{row.classList.toggle('hidden',!!q&&!row.textContent.toLowerCase().includes(q))})};
$('savedAttach').onclick=()=>$('savedFile').click();
$('savedFile').onchange=async()=>{const f=$('savedFile').files[0];if(!f)return;try{showToast('در حال آپلود…');const fd=new FormData();fd.append('file',f);const u=await api('/api/upload',{method:'POST',body:fd});const kind=f.type==='image/gif'?'gif':f.type.startsWith('image/')?'image':f.type.startsWith('video/')?'video':f.type.startsWith('audio/')?'audio':'file';const m=await api('/api/saved/chat/messages',{method:'POST',body:JSON.stringify({text:'',fileUrl:u.url,fileType:u.mime,fileName:u.name,kind})});appendSavedMessage(m);$('savedFile').value='';const x=$('savedList');x.scrollTop=x.scrollHeight}catch(e){showToast(e.message,true)}};
$('savedComposer').onsubmit=async e=>{e.preventDefault();const input=$('savedText');const text=input.value.trim();if(!text)return;try{const m=await api('/api/saved/chat/messages',{method:'POST',body:JSON.stringify({text})});appendSavedMessage(m);input.value='';const x=$('savedList');x.scrollTop=x.scrollHeight}catch(err){showToast(err.message,true)}};
async function openSettings(){await loadSettings();renderSettings('notifications');$('settingsModal').classList.remove('hidden')}$('closeSettings').onclick=()=>$('settingsModal').classList.add('hidden');document.querySelectorAll('#settingsNav button').forEach(b=>b.onclick=()=>{document.querySelectorAll('#settingsNav button').forEach(x=>x.classList.remove('active'));b.classList.add('active');renderSettings(b.dataset.section)});
function renderSettings(section){const c=$('settingsContent');const on=(obj,k)=>obj?.[k]!==false;const row=(label,desc,path)=>{const parts=path.split('.'),obj=settings[parts[0]]||{},key=parts[1];return `<div class="setting-row"><div><b>${label}</b><small>${desc}</small></div><button class="switch ${on(obj,key)?'on':''}" data-setting="${path}"></button></div>`};if(section==='notifications')c.innerHTML=`<div class="settings-content"><div class="settings-section"><h4>اعلان‌ها</h4>${row('اعلان پیام‌ها','دریافت اعلان برای پیام‌های جدید','notifications.messages')}${row('صدای اعلان','پخش صدای پیام جدید','notifications.sounds')}${row('نمایش پیش‌نمایش','متن پیام در اعلان نمایش داده شود','notifications.previews')}<div class="setting-row"><div><b>صدای اعلان</b><small>انتخاب افکت اعلان پیام</small></div><select id="notificationSound" class="select-setting"><option value="default">پیش‌فرض</option><option value="soft">آرام</option><option value="pop">پاپ</option></select></div><button id="enableNotificationsBtn" class="secondary full">فعال‌سازی اعلان‌های دستگاه</button></div></div>`;else if(section==='calls')c.innerHTML=`<div class="settings-content"><h4>تماس‌ها</h4><div class="call-settings-card"><div class="setting-row"><div><b>آهنگ زنگ تماس</b><small>هر فایل صوتی دلخواه را برای تماس ورودی انتخاب کن.</small></div><select id="callRingtone" class="select-setting"><option value="classic">کلاسیک</option><option value="soft">آرام</option><option value="digital">دیجیتال</option><option value="custom">آهنگ آپلودشده</option></select></div><div class="ringtone-upload-row"><input id="callRingtoneFile" type="file" accept="audio/*" hidden><button id="uploadCallRingtone" class="secondary">🎵 انتخاب و آپلود آهنگ</button><span id="callRingtoneName" class="setting-file-name"></span></div><div class="ringtone-preview-row"><button id="previewCallRingtone" class="secondary">▶️ پخش آزمایشی</button><button id="removeCallRingtone" class="secondary danger">🗑️ حذف آهنگ شخصی</button></div><div class="setting-row"><div><b>بلندی زنگ</b><small>شدت صدای زنگ تماس</small></div><input id="callRingVolume" type="range" min="0" max="1" step="0.05"></div>${row('صدای ورود به کنفرانس','پخش صدای کوتاه هنگام ورود/خروج','calls.conferenceTone')}<div class="call-timeout-note">⏱️ اگر تماس ورودی تا <b>۱ دقیقه</b> پاسخ داده نشود، تماس خودکار قطع می‌شود.</div></div></div>`;else if(section==='data')c.innerHTML=`<div class="settings-content"><h4>داده و رسانه</h4>${row('پخش خودکار','رسانه‌ها خودکار پخش شوند','data_usage.autoplay')}${row('دانلود خودکار عکس','در شبکه‌های معمولی','data_usage.autoDownloadImages')}${row('دانلود خودکار ویدیو','برای کاهش مصرف اینترنت خاموش باشد','data_usage.autoDownloadVideos')}${row('دانلود خودکار صدا','برای کاهش مصرف اینترنت خاموش باشد','data_usage.autoDownloadAudio')}</div>`;else if(section==='privacy')c.innerHTML=`<div class="settings-content"><h4>حریم خصوصی</h4>${row('تیک خوانده‌شدن','وضعیت خوانده‌شدن پیام‌ها','privacy.readReceipts')}<div class="danger-setting"><b>حذف حساب کاربری</b><small>این عملیات دائمی است و قابل بازگشت نیست.</small><button id="deleteAccountBtn" class="danger">حذف حساب</button></div><div class="setting-row"><div><b>آخرین بازدید</b><small>چه کسانی وضعیت آنلاین شما را ببینند</small></div><select class="select-setting" id="lastSeen"><option value="everyone">همه</option><option value="contacts">مخاطبین</option><option value="nobody">هیچ‌کس</option></select></div><div class="setting-row"><div><b>عکس پروفایل</b><small>چه کسانی عکس شما را ببینند</small></div><select class="select-setting" id="profilePhoto"><option value="everyone">همه</option><option value="contacts">مخاطبین</option><option value="nobody">هیچ‌کس</option></select></div></div>`;else if(section==='security')c.innerHTML=`<div class="settings-content"><h4>امنیت</h4>${row('تأیید دومرحله‌ای','پرچم تنظیمات امنیتی حساب','security.twoStep')}<div class="setting-row"><div><b>نشست فعلی</b><small>JWT امن با اعتبار ۷ روزه</small></div><span>✓ فعال</span></div></div>`;else c.innerHTML=`<div class="settings-content"><h4>ظاهر</h4>${row('حالت شب','پوسته تیره','appearance.dark')}${row('نمای فشرده','فاصله کمتر بین پیام‌ها','appearance.compact')}</div>`;if(section==='privacy'){$('deleteAccountBtn')?.addEventListener('click',async()=>{if(!confirm('حذف دائمی حساب؟'))return;try{await api('/api/account',{method:'DELETE'});logout()}catch(e){showToast(e.message,true)}});$('lastSeen').value=settings.privacy?.lastSeen||'everyone';$('profilePhoto').value=settings.privacy?.profilePhoto||'everyone';$('lastSeen').onchange=saveSettingsFromUI;$('profilePhoto').onchange=saveSettingsFromUI}if(section==='notifications'){$('notificationSound').value=settings.notifications?.sound||'default';$('notificationSound').onchange=saveSettingsFromUI;$('enableNotificationsBtn').onclick=async()=>{try{if('Notification' in window)await Notification.requestPermission();await setupBrowserNotifications();showToast('اعلان‌های دستگاه فعال شد ✓')}catch(e){showToast('فعال‌سازی اعلان ناموفق بود',true)}}}if(section==='calls'){const rt=settings.calls?.ringtone||'classic';$('callRingtone').value=settings.calls?.ringtoneUrl?'custom':rt;$('callRingVolume').value=String(settings.calls?.ringVolume??.8);$('callRingtoneName').textContent=settings.calls?.ringtoneName||'';$('callRingtone').onchange=saveSettingsFromUI;$('callRingVolume').oninput=saveSettingsFromUI;$('uploadCallRingtone').onclick=()=>$('callRingtoneFile').click();$('callRingtoneFile').onchange=uploadCallRingtone;$('previewCallRingtone').onclick=()=>previewCallRingtone();$('removeCallRingtone').onclick=removeCallRingtone}c.querySelectorAll('[data-setting]').forEach(b=>b.onclick=()=>{const [group,key]=b.dataset.setting.split('.');settings[group]??={};settings[group][key]=!b.classList.contains('on');b.classList.toggle('on');saveSettingsFromUI()});applyControlLabels()}
async function uploadCallRingtone(){const f=$('callRingtoneFile')?.files?.[0];if(!f)return;if(!f.type.startsWith('audio/'))return showToast('فقط فایل صوتی مجاز است',true);if(f.size>20*1024*1024)return showToast('حجم آهنگ باید کمتر از ۲۰ مگابایت باشد',true);try{const fd=new FormData();fd.append('file',f,f.name);const u=await api('/api/upload',{method:'POST',body:fd});settings.calls={...(settings.calls||{}),ringtone:'custom',ringtoneUrl:u.url,ringtoneName:u.name};await api('/api/settings',{method:'PUT',body:JSON.stringify(settings)});$('callRingtone').value='custom';$('callRingtoneName').textContent=u.name;showToast('آهنگ زنگ تماس ذخیره شد ✓')}catch(e){showToast(e.message||'آپلود آهنگ ناموفق بود',true)}}
function previewCallRingtone(){const url=settings.calls?.ringtoneUrl;if(!url)return playRingtone();stopRingtone();const a=new Audio(backendUrl(url));a.volume=Number(settings.calls?.ringVolume??.8);a.play().catch(()=>showToast('برای پخش آزمایشی روی صفحه تعامل کنید',true));setTimeout(()=>{a.pause();a.currentTime=0},10000)}
async function removeCallRingtone(){if(!settings.calls?.ringtoneUrl)return;settings.calls.ringtoneUrl='';settings.calls.ringtoneName='';settings.calls.ringtone='classic';try{await api('/api/settings',{method:'PUT',body:JSON.stringify(settings)});renderSettings('calls');showToast('آهنگ شخصی حذف شد')}catch(e){showToast(e.message,true)}}
async function saveSettingsFromUI(){try{if($('lastSeen'))settings.privacy.lastSeen=$('lastSeen').value;if($('profilePhoto'))settings.privacy.profilePhoto=$('profilePhoto').value;if($('callRingVolume'))settings.calls.ringVolume=Number($('callRingVolume').value);if($('callRingtone')){const v=$('callRingtone').value;if(v!=='custom'){settings.calls.ringtone=v;settings.calls.ringtoneUrl='';settings.calls.ringtoneName=''}}await api('/api/settings',{method:'PUT',body:JSON.stringify(settings)});if($('callRingtone'))showToast('تنظیمات تماس ذخیره شد ✓');else showToast('تنظیمات ذخیره شد')}catch(e){showToast(e.message,true)}}
