async function promoteAdmin(uid){try{if(!adminConversation.isOwner)return showToast('فقط مالک می‌تواند ادمین اضافه کند',true);await api(`/api/conversations/${adminConversation.id}/admins`,{method:'POST',body:JSON.stringify({userId:uid,permissions:{post:true,edit:true,delete:true,invite:true,ban:true,manage:true}})});adminConversation=await api(`/api/conversations/${adminConversation.id}/management`);showToast('ادمین اضافه شد');renderAdminTab('admins')}catch(e){showToast(e.message,true)}}
async function kickMember(uid){try{await api(`/api/conversations/${adminConversation.id}/members/${uid}`,{method:'DELETE'});adminConversation.members=adminConversation.members.filter(u=>Number(u.id)!==uid);renderAdminTab('members');loadConvs();showToast('عضو حذف شد')}catch(e){showToast(e.message,true)}}
$('search').oninput=()=>{clearTimeout(searchTimer);const q=$('search').value.trim();$('clearSearch').classList.toggle('hidden',!q);if(!q){$('userResults').innerHTML='';return}searchTimer=setTimeout(async()=>{try{const us=await api('/api/users?q='+encodeURIComponent(q));$('userResults').innerHTML=us.map(u=>`<button class="result-item" data-user="${u.id}">${avatar(u,'avatar')}<span><b>${esc(u.display_name)}</b><small>@${esc(u.username)}</small></span></button>`).join('');$('userResults').querySelectorAll('[data-user]').forEach(b=>b.onclick=async()=>{const c=await api('/api/conversations/direct',{method:'POST',body:JSON.stringify({userId:Number(b.dataset.user)})});$('search').value='';$('userResults').innerHTML='';await loadConvs();openConv(c.id)})}catch(e){showToast(e.message,true)}},250)};$('clearSearch').onclick=()=>{$('search').value='';$('userResults').innerHTML='';$('clearSearch').classList.add('hidden')};document.querySelectorAll('.chat-tabs button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.chat-tabs button').forEach(x=>x.classList.remove('active'));b.classList.add('active');activeFilter=b.dataset.filter;renderConvs()});
async function logout(){localStorage.removeItem('zento_token');token=null;socket?.disconnect();showAuth()}
$('lightboxClose').onclick=()=>$('lightbox').classList.add('hidden');
let customMediaElement=null;let customMediaObjectUrl=null;let customImageScale=1;
function fmtMediaTime(sec){if(!Number.isFinite(sec))return '00:00';sec=Math.max(0,Math.floor(sec));const h=Math.floor(sec/3600),m=Math.floor((sec%3600)/60),s=sec%60;return h?`${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}`:`${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`}
function bindInlineAudioPlayers(root=document){root.querySelectorAll?.('.inline-audio-player').forEach(box=>{if(box.dataset.audioBound)return;box.dataset.audioBound='1';const a=box.querySelector('audio'),play=box.querySelector('.inline-audio-play'),seek=box.querySelector('.inline-audio-seek'),time=box.querySelector('.inline-audio-time'),speed=box.querySelector('.inline-audio-speed'),mute=box.querySelector('.inline-audio-mute');if(!a)return;const fmt=t=>{t=Number.isFinite(t)?Math.max(0,t):0;const m=Math.floor(t/60),sec=Math.floor(t%60);return `${m}:${String(sec).padStart(2,'0')}`};const refresh=()=>{const d=a.duration||0;seek.value=d?(a.currentTime/d*100):0;time.textContent=`${fmt(a.currentTime)} / ${fmt(d)}`;play.textContent=a.paused?'▶':'⏸'};a.addEventListener('loadedmetadata',refresh);a.addEventListener('timeupdate',refresh);a.addEventListener('play',refresh);a.addEventListener('pause',refresh);a.addEventListener('ended',()=>{a.currentTime=0;refresh()});play.onclick=()=>{document.querySelectorAll('.inline-audio-player audio').forEach(x=>{if(x!==a)x.pause()});a.paused?a.play().catch(()=>{}):a.pause()};seek.oninput=()=>{if(a.duration)a.currentTime=(Number(seek.value)/100)*a.duration};speed.onclick=()=>{const speeds=[1,1.25,1.5,2];const n=speeds[(speeds.indexOf(a.playbackRate)+1)%speeds.length];a.playbackRate=n;speed.textContent=n+'×'};mute.onclick=()=>{a.muted=!a.muted;mute.textContent=a.muted?'🔇':'🔊'};refresh()})}

function closeCustomMedia(){const modal=$('mediaPlayerModal');if(customMediaElement){try{customMediaElement.pause()}catch{}customMediaElement.src='';customMediaElement.remove()}if(customMediaObjectUrl){URL.revokeObjectURL(customMediaObjectUrl);customMediaObjectUrl=null}customMediaElement=null;modal.classList.add('hidden');modal.setAttribute('aria-hidden','true');$('customMediaStage').innerHTML='';$('customMediaShell').className='custom-media-shell';}
function bindCustomMediaTriggers(root=document){root.querySelectorAll?.('.custom-media-trigger').forEach(btn=>{if(btn.dataset.mediaBound)return;btn.dataset.mediaBound='1';btn.addEventListener('click',()=>openCustomMedia(btn.dataset.mediaKind,btn.dataset.mediaUrl,btn.dataset.mediaTitle))})}
function openCustomMedia(kind,url,title='رسانه'){closeCustomMedia();const modal=$('mediaPlayerModal'),stage=$('customMediaStage'),controls=$('customMediaControls'),imgControls=$('customImageControls');$('customMediaTitle').textContent=title;$('customMediaKind').textContent=kind==='image'?'تصویر':kind==='video'?'ویدیو':kind==='document'?'سند':'موقعیت';modal.classList.remove('hidden');modal.setAttribute('aria-hidden','false');customImageScale=1;
  if(kind==='document'){stage.innerHTML=`<div class=\"document-viewer\"><div class=\"document-toolbar\"><span>📄 ${esc(title)}</span><a href=\"${esc(url)}\" target=\"_blank\" rel=\"noopener\">باز کردن جداگانه ↗</a></div><iframe title=\"${esc(title)}\" src=\"${esc(url)}#toolbar=0&navpanes=0&view=FitH\"></iframe></div>`;controls.classList.add('hidden');imgControls.classList.add('hidden');$('customMediaMeta').textContent='نمایشگر اختصاصی سند زنتو • بدون پنل پیش‌فرض گوگل';return}
  if(kind==='location'){stage.innerHTML=`<div class=\"document-viewer location-viewer\"><div class=\"location-map-big\"><iframe title=\"موقعیت مکانی\" src=\"${esc(url)}\"></iframe></div><div class=\"location-actions\"><a href=\"${esc(url)}\" target=\"_blank\" rel=\"noopener\">باز کردن نقشه ↗</a></div></div>`;controls.classList.add('hidden');imgControls.classList.add('hidden');$('customMediaMeta').textContent='نمایشگر موقعیت مکانی زنتو';return}
  if(kind==='image'){customMediaElement=document.createElement('img');customMediaElement.src=url;customMediaElement.alt=title;customMediaElement.className='custom-player-image';stage.appendChild(customMediaElement);controls.classList.add('hidden');imgControls.classList.remove('hidden');$('customMediaMeta').textContent='تصویر با کیفیت • برای بزرگ‌نمایی از کنترل‌های پایین استفاده کن';return}
  imgControls.classList.add('hidden');controls.classList.remove('hidden');customMediaElement=document.createElement(kind==='video'?'video':'audio');customMediaElement.src=url;customMediaElement.preload='metadata';customMediaElement.playsInline=true;customMediaElement.className=kind==='video'?'custom-player-video':'custom-player-audio';stage.appendChild(customMediaElement);$('customMediaMeta').textContent=kind==='video'?'ویدیو مسیج / ویدیو • پلیر اختصاصی زنتو':'پیام صوتی / آهنگ • پلیر اختصاصی زنتو';$('customMediaSeek').value=0;$('customMediaCurrent').textContent='00:00';$('customMediaDuration').textContent='00:00';$('customMediaPlay').textContent='▶';$('customMediaMute').textContent='🔊';
  customMediaElement.addEventListener('loadedmetadata',()=>{$('customMediaDuration').textContent=fmtMediaTime(customMediaElement.duration);$('customMediaSeek').max=Math.max(1,customMediaElement.duration||1)});customMediaElement.addEventListener('timeupdate',()=>{const d=customMediaElement.duration||1;$('customMediaSeek').value=customMediaElement.currentTime;$('customMediaSeek').max=d;$('customMediaCurrent').textContent=fmtMediaTime(customMediaElement.currentTime)});customMediaElement.addEventListener('play',()=>$('customMediaPlay').textContent='⏸');customMediaElement.addEventListener('pause',()=>$('customMediaPlay').textContent='▶');customMediaElement.addEventListener('ended',()=>{$('customMediaPlay').textContent='▶';customMediaElement.currentTime=0});
}
$('customMediaClose').onclick=closeCustomMedia;$('mediaPlayerModal').addEventListener('click',e=>{if(e.target===$('mediaPlayerModal'))closeCustomMedia()});$('customMediaPlay').onclick=()=>{if(!customMediaElement)return;if(customMediaElement.paused)customMediaElement.play().catch(()=>{});else customMediaElement.pause()};$('customMediaSeek').oninput=e=>{if(customMediaElement)customMediaElement.currentTime=Number(e.target.value)};$('customMediaMute').onclick=()=>{if(!customMediaElement)return;customMediaElement.muted=!customMediaElement.muted;$('customMediaMute').textContent=customMediaElement.muted?'🔇':'🔊'};$('customMediaSpeed').onclick=()=>{if(!customMediaElement)return;const speeds=[1,1.25,1.5,1.75,2];const i=speeds.indexOf(customMediaElement.playbackRate);const n=speeds[(i+1)%speeds.length];customMediaElement.playbackRate=n;$('customMediaSpeed').textContent=n+'×'};$('customMediaFullscreen').onclick=()=>{const el=customMediaElement?.requestFullscreen?customMediaElement:$('customMediaShell');el?.requestFullscreen?.().catch(()=>{})};document.querySelectorAll('[data-zoom]').forEach(b=>b.onclick=()=>{if(!customMediaElement||customMediaElement.tagName!=='IMG')return;const z=b.dataset.zoom;if(z==='in')customImageScale=Math.min(3,customImageScale+.25);else if(z==='out')customImageScale=Math.max(.5,customImageScale-.25);else if(z==='reset')customImageScale=1;else if(z==='fit')customImageScale=1;customMediaElement.style.transform=`scale(${customImageScale})`});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('mediaPlayerModal').classList.contains('hidden'))closeCustomMedia()});bindCustomMediaTriggers();

// Make control-heavy panels readable: emoji + explicit text, never icon-only.
function applyControlLabels(){
  const labels={
    chatSearch:['🔎','جستجو'],callAudio:['📞','تماس صوتی'],callVideo:['📹','تماس تصویری'],callConference:['👥','کنفرانس'],chatMore:['•••','بیشتر'],
    emoji:['😀','ایموجی'],attach:['📎','پیوست'],voice:['🎙️','ویس'],videoVoice:['🎥','ویدیو مسیج'],send:['➤','ارسال'],botCommandsToggle:['🧩','دکمه‌ها'],
    speakerCall:['🔊','بلندگو'],muteCall:['🎙️','میکروفون'],cameraCall:['📷','دوربین'],screenShareCall:['🖥️','اشتراک صفحه'],conferenceCall:['👥','کنفرانس'],endCall:['📵','قطع تماس']
  };
  Object.entries(labels).forEach(([id,[emoji,text]])=>{const b=$(id);if(!b)return;if(!b.querySelector('.control-label'))b.innerHTML=`<span class="control-emoji">${emoji}</span><span class="control-label">${text}</span>`});
  document.querySelectorAll('#settingsNav button').forEach(b=>{if(b.querySelector('span'))return;const t=b.textContent.trim();const m=t.match(/^(.+?)\s+(.+)$/);if(m)b.innerHTML=`<span class="control-emoji">${m[1]}</span><span class="control-label">${m[2]}</span>`});
}
applyControlLabels();
// Auth tabs
$('loginForm').onsubmit=async e=>{e.preventDefault();try{const r=await api('/api/login',{method:'POST',body:JSON.stringify({email:$('loginEmail').value,password:$('loginPass').value})});token=r.token;localStorage.setItem('zento_token',token);await boot()}catch(err){showToast(err.message,true)}};$('registerForm').onsubmit=async e=>{e.preventDefault();try{const r=await api('/api/register',{method:'POST',body:JSON.stringify({displayName:$('regName').value,email:$('regEmail').value,password:$('regPass').value})});token=r.token;localStorage.setItem('zento_token',token);await boot()}catch(err){showToast(err.message,true)}};document.querySelectorAll('.tabs button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.tabs button').forEach(x=>x.classList.remove('active'));b.classList.add('active');$('loginForm').classList.toggle('hidden',b.dataset.tab!=='login');$('registerForm').classList.toggle('hidden',b.dataset.tab!=='register')});
// WebRTC calling
function installCallHandlers(){if(!socket)return;socket.on('call:offer',async d=>incomingCall(d));socket.on('call:answer',async d=>{try{if(call?.pc){call.callId=d.callId||call.callId;await call.pc.setRemoteDescription(new RTCSessionDescription(d.answer));}$('callStatusText').textContent='متصل'}catch(e){console.error('call answer',e);showToast('برقراری تماس ناموفق بود',true)}});socket.on('call:ice',async d=>{try{if(call?.pc&&d.candidate)await call.pc.addIceCandidate(new RTCIceCandidate(d.candidate))}catch(e){console.warn('call ice',e)}});socket.on('call:end',()=>endCall(false))}
async function startCall(video){if(current?.type==='direct' && current.members?.find(x=>Number(x.id)!==Number(me.id))?.is_bot)return showToast('تماس با ربات‌ها امکان‌پذیر نیست',true);if(!current||current.type!=='direct')return showToast('تماس فقط در گفتگوی خصوصی فعال است',true);const other=current.members.find(x=>Number(x.id)!==Number(me.id));if(!other)return;await openCallUI(other,video,false);call.pc=new RTCPeerConnection({iceServers:CALL_ICE});call.pc.onconnectionstatechange=()=>{const st=call?.pc?.connectionState;if(st==='connected'){ $('callStatusText').textContent='متصل'; startCallTimer(); }if(['failed','disconnected'].includes(st)){$('callStatusText').textContent='اتصال ناموفق یا ناپایدار است';showToast('تماس نتوانست برقرار شود؛ شبکه یا دسترسی میکروفون/دوربین را بررسی کن',true)}};call.pc.onicecandidate=e=>e.candidate&&socket.emit('call:ice',{to:other.id,candidate:e.candidate});call.pc.ontrack=e=>{const v=$('remoteVideo');if(!v.srcObject)v.srcObject=new MediaStream();const incoming=e.streams?.[0];if(incoming){incoming.getTracks().forEach(t=>{if(!v.srcObject.getTracks().some(x=>x.id===t.id))v.srcObject.addTrack(t)})}else if(e.track&&!v.srcObject.getTracks().some(x=>x.id===e.track.id)){v.srcObject.addTrack(e.track)}v.classList.remove('hidden');$('callAvatar').style.display='none';v.onloadedmetadata=()=>v.play().catch(()=>{});v.play?.().catch(()=>{});};const stream=await navigator.mediaDevices.getUserMedia({audio:true,video:video});call.local=stream;$('localVideo').srcObject=stream;stream.getTracks().forEach(t=>call.pc.addTrack(t,stream));const offer=await call.pc.createOffer();await call.pc.setLocalDescription(offer);socket.emit('call:offer',{to:other.id,offer,video});$('callStatusText').textContent='در انتظار پاسخ…';call.answerTimeout=setTimeout(()=>{if(call&&!call.incoming){showToast('پاسخی دریافت نشد؛ تماس پس از ۱ دقیقه خودکار قطع شد');endCall(true,'missed')}},60000)}
async function incomingCall(d){const u=convs.flatMap(c=>c.members).find(x=>Number(x.id)===Number(d.from))||{display_name:'کاربر',id:d.from};if(u.is_bot)return;await openCallUI(u,d.video,true);const c=call;c.callId=d.callId||null;c.pc=new RTCPeerConnection({iceServers:CALL_ICE});c.pc.onicecandidate=e=>e.candidate&&socket.emit('call:ice',{to:u.id,candidate:e.candidate});c.pc.ontrack=e=>{const v=$('remoteVideo');if(!v.srcObject)v.srcObject=new MediaStream();const incoming=e.streams?.[0];if(incoming){incoming.getTracks().forEach(t=>{if(!v.srcObject.getTracks().some(x=>x.id===t.id))v.srcObject.addTrack(t)})}else if(e.track&&!v.srcObject.getTracks().some(x=>x.id===e.track.id)){v.srcObject.addTrack(e.track)}v.classList.remove('hidden');$('callAvatar').style.display='none';v.onloadedmetadata=()=>v.play().catch(()=>{});v.play?.().catch(()=>{});};await c.pc.setRemoteDescription(new RTCSessionDescription(d.offer));c.answerTimeout=setTimeout(()=>{if(call?.incoming){showToast('تماس بدون پاسخ پس از ۱ دقیقه پایان یافت');endCall(true,'missed')}},60000);$('callStatusText').textContent='تماس ورودی — پاسخ دهید'}
function startCallTimer(){if(!call)return;clearInterval(call.timer);call.startedAt=Date.now();$('callModal')?.classList.add('call-connected');call.timer=setInterval(()=>{if(!call)return;const s=Math.floor((Date.now()-call.startedAt)/1000);const mm=String(Math.floor(s/60)).padStart(2,'0'),ss=String(s%60).padStart(2,'0');if($('callTimer'))$('callTimer').textContent=`${mm}:${ss}`},500)}
function resetCallTimer(){if(call?.timer)clearInterval(call.timer);$('callModal')?.classList.remove('call-connected');if($('callTimer'))$('callTimer').textContent='00:00'}
let ringtoneAudio=null,ringtoneLoop=null;
function stopRingtone(){if(ringtoneLoop){clearInterval(ringtoneLoop);ringtoneLoop=null}if(ringtoneAudio){try{ringtoneAudio.pause();ringtoneAudio.currentTime=0}catch{}ringtoneAudio=null}}
function playRingtone(){stopRingtone();const vol=Number(settings?.calls?.ringVolume??.8),url=settings?.calls?.ringtoneUrl;if(url){ringtoneAudio=new Audio(backendUrl(url));ringtoneAudio.loop=true;ringtoneAudio.volume=vol;ringtoneAudio.play().catch(()=>{});return}try{const C=window.AudioContext||window.webkitAudioContext;if(!C)return;const beep=()=>{try{const ctx=new C(),o=ctx.createOscillator(),g=ctx.createGain();o.frequency.value=settings?.calls?.ringtone==='digital'?740:settings?.calls?.ringtone==='soft'?520:620;g.gain.value=.06*vol;o.connect(g);g.connect(ctx.destination);o.start();setTimeout(()=>{o.stop();ctx.close().catch(()=>{})},450)}catch{}};beep();ringtoneLoop=setInterval(beep,1400)}catch{}}
async function openCallHistory(){try{const rows=await api('/api/calls/history');const fmtDate=v=>{try{return new Intl.DateTimeFormat('fa-IR',{dateStyle:'medium',timeStyle:'short'}).format(new Date(v))}catch{return new Date(v).toLocaleString()}};const fmtDur=v=>{const sec=Number(v||0),m=Math.floor(sec/60),ss=sec%60;return m?`${m} دقیقه و ${ss} ثانیه`:`${ss} ثانیه`};const body=rows.length?`<div class="call-history-list">${rows.map(x=>{const other=Number(x.caller_id)===Number(me.id)?{name:x.receiver_name,username:x.receiver_username,avatar:x.receiver_avatar}:{name:x.caller_name,username:x.caller_username,avatar:x.caller_avatar};const missed=x.status==='ringing'||x.status==='missed';const label=x.status==='rejected'?'رد شده':x.status==='cancelled'?'لغو شده':missed?'بی‌پاسخ':x.status==='completed'?'مکالمه':'پایان تماس';return `<div class="call-history-item">${avatar({display_name:other.name,avatar:other.avatar},'avatar tiny-avatar')}<div class="chi-main"><b>${esc(other.name||'کاربر')}</b><small>@${esc(other.username||'')} · ${esc(fmtDate(x.created_at))}</small></div><div class="chi-meta"><span class="chi-status ${x.is_outgoing?'out':'in'} ${missed?'missed':''}">${x.is_outgoing?'↗ خروجی':'↙ ورودی'} · ${label}</span><span>⏱ ${fmtDur(x.duration)}</span></div></div>`}).join('')}</div>`:'<div class="empty"><b>تاریخچه تماس خالی است</b><span>تماس‌های صوتی و تصویری بعد از پایان در اینجا ثبت می‌شوند.</span></div>';openModal('📞 تاریخچه تماس‌ها',body,()=>{});$('modalOk').classList.add('hidden');$('modalCancel').textContent='بستن'}catch(e){showToast(e.message,true)}}

async function openCallUI(other,video,incoming){call={other,video,incoming,pc:null,local:null,callId:null,remoteZoom:false,localZoom:false};$('callModal').classList.remove('hidden');$('callType').textContent=video?'تماس تصویری':'تماس صوتی';$('callName').textContent=other.display_name||'تماس';$('callAvatar').innerHTML=other.avatar?`<img src="${esc(backendUrl(other.avatar))}" alt="پروفایل ${esc(other.display_name||'کاربر')}">`:`${esc((other.display_name||'گ')[0])}`;$('callAvatar').style.display='grid';$('cameraCall').style.display=video?'flex':'none';$('localVideo').classList.toggle('hidden',!video);$('localVideoWrap').classList.toggle('hidden',!video);$('remoteVideo').classList.toggle('hidden',!video);$('remoteVideo').srcObject=null;$('callTimer').textContent='00:00';$('callStatusText').textContent=incoming?'تماس ورودی — پاسخ یا رد تماس':'در حال برقراری تماس…';$('acceptCall').classList.toggle('hidden',!incoming);$('rejectCall').classList.toggle('hidden',!incoming);$('endCall').classList.toggle('hidden',!!incoming);$('remoteZoomCall').classList.toggle('hidden',!video);$('localZoomCall').classList.toggle('hidden',!video);$('remoteWrap')?.classList.remove('zoomed');$('localVideoWrap')?.classList.remove('zoomed');if(incoming)playRingtone();}

$('closeProfile')?.addEventListener('click',()=>{$('profileModal').classList.add('hidden')});
$('remoteZoomCall').onclick=()=>{if(!call?.video)return;call.remoteZoom=!call.remoteZoom;$('remoteWrap')?.classList.toggle('zoomed',call.remoteZoom);$('remoteZoomCall').textContent=call.remoteZoom?'⤡':'⛶'};$('localZoomCall').onclick=()=>{if(!call?.video)return;call.localZoom=!call.localZoom;$('localVideoWrap')?.classList.toggle('zoomed',call.localZoom);$('localZoomCall').textContent=call.localZoom?'⤡':'⛶'};
$('callAudio').onclick=()=>startCall(false);$('callVideo').onclick=()=>startCall(true);$('endCall').onclick=()=>endCall(true,'completed');$('rejectCall').onclick=()=>endCall(true,'rejected');$('acceptCall').onclick=async()=>{if(!call?.incoming)return;try{const c=call;if(c.answerTimeout)clearTimeout(c.answerTimeout);stopRingtone();const stream=await navigator.mediaDevices.getUserMedia({audio:true,video:c.video});c.local=stream;$('localVideo').srcObject=stream;stream.getTracks().forEach(t=>c.pc.addTrack(t,stream));const answer=await c.pc.createAnswer();await c.pc.setLocalDescription(answer);socket.emit('call:answer',{to:c.other.id,answer,callId:c.callId||null});$('acceptCall').classList.add('hidden');$('rejectCall').classList.add('hidden');$('endCall').classList.remove('hidden');$('callStatusText').textContent='متصل';startCallTimer();}catch(e){showToast('دسترسی دوربین/میکروفون ممکن نیست',true)}};
async function incomingSetup(){ }
async function endCall(send=true,reason=null){if(!call)return;const c=call;if(c.answerTimeout)clearTimeout(c.answerTimeout);stopRingtone();let duration=0;if(c.startedAt)duration=Math.max(0,Math.floor((Date.now()-c.startedAt)/1000));if(send&&socket)socket.emit('call:end',{to:c.other.id,callId:c.callId||null,duration,reason:reason||((c.incoming&&duration===0)?'rejected':(duration>0?'completed':'cancelled'))});resetCallTimer();c.local?.getTracks().forEach(t=>t.stop());c.pc?.close();call=null;$('callModal').classList.add('hidden');$('remoteVideo').srcObject=null;$('remoteVideo').classList.add('hidden');$('callAvatar').style.display='grid';$('localVideo').srcObject=null;$('acceptCall').classList.add('hidden');$('rejectCall').classList.add('hidden');$('remoteZoomCall')?.classList.add('hidden');$('localZoomCall')?.classList.add('hidden')}
$('muteCall').onclick=()=>{const t=call?.local?.getAudioTracks()[0];if(t){t.enabled=!t.enabled;$('muteCall').textContent=t.enabled?'🎙':'🔇'}};$('cameraCall').onclick=()=>{const t=call?.local?.getVideoTracks()[0];if(t)t.enabled=!t.enabled};$('screenShareCall').onclick=()=>{if(!call)return showToast('ابتدا تماس تصویری برقرار کن',true);if(!call.video)return showToast('اشتراک صفحه در تماس صوتی فعال نیست',true);toggleScreenShare()};$('speakerCall').onclick=()=>showToast('کنترل صدای تماس از تنظیمات دستگاه انجام می‌شود');

/* ================= Zento Conference Calls ================= */
let conference=null;
function conferenceUserList(){if(!current)return[];return (current.members||[]).filter(u=>Number(u.id)!==Number(me.id));}
function openConferenceChooser(){
  if(!current)return showToast('ابتدا یک گفتگو را انتخاب کن',true);
  if(current.type==='channel')return showToast('کنفرانس در کانال در دسترس نیست',true);
  if(current.type==='direct'){
    const currentOther=current.members?.find(u=>Number(u.id)!==Number(me.id)&&!u.is_bot);
    if(!currentOther)return showToast('کاربر قابل دعوتی وجود ندارد',true);
    const candidates=[];const seen=new Set([Number(me.id),Number(currentOther.id)]);
    convs.forEach(c=>{if(c.type!=='direct')return;const u=c.members?.find(x=>Number(x.id)!==Number(me.id)&&!x.is_bot);if(u&&!seen.has(Number(u.id))){seen.add(Number(u.id));candidates.push(u)}});
    openModal('👥 کنفرانس زنتو',`<div class="conference-panel"><div class="conference-hero"><div class="conference-icon">📞</div><b>افزودن افراد به تماس</b><small>تماس خصوصی فعلی را به یک کنفرانس چندنفره تبدیل کن.</small></div><div class="conference-member"><div>${avatar(currentOther,'avatar tiny-avatar')}</div><span><b>${esc(currentOther.display_name)}</b><small>طرف تماس فعلی</small></span><input type="checkbox" checked disabled></div><div class="conference-list">${candidates.map(u=>`<label class="conference-member conference-select">${avatar(u,'avatar tiny-avatar')}<span><b>${esc(u.display_name)}</b><small>@${esc(u.username||'')}</small></span><input type="checkbox" data-conf-user="${u.id}"></label>`).join('')||'<div class="empty">مخاطب دیگری برای دعوت پیدا نشد.</div>'}</div><button id="startConferenceBtn" class="primary full">🚀 شروع کنفرانس</button></div>`,()=>{});$('modalOk').classList.add('hidden');$('modalCancel').textContent='بستن';$('startConferenceBtn').onclick=async()=>{const ids=[Number(currentOther.id),...Array.from(document.querySelectorAll('[data-conf-user]:checked')).map(x=>Number(x.dataset.confUser))];const videoMode=call?.video!==false;if(call)endCall(false);try{const g=await api('/api/conversations/group',{method:'POST',body:JSON.stringify({name:'کنفرانس خصوصی',members:[...new Set(ids)]})});closeModal();convs=convs.some(x=>Number(x.id)===Number(g.id))?convs.map(x=>Number(x.id)===Number(g.id)?g:x):[g,...convs];await openConv(Number(g.id));startConference(videoMode)}catch(e){showToast(e.message,true)}};
    return;
  }
  if(current.type!=='group')return showToast('کنفرانس فقط در گروه یا تماس خصوصی قابل استفاده است',true);
  const members=conferenceUserList();if(!members.length)return showToast('عضوی برای کنفرانس وجود ندارد',true);
  openModal('👥 کنفرانس زنتو',`<div class="conference-panel"><div class="conference-hero"><div class="conference-icon">👥</div><b>تماس گروهی</b><small>همه اعضای این گفتگو می‌توانند وارد اتاق کنفرانس شوند.</small></div><div class="conference-list">${members.map(u=>`<div class="conference-member">${avatar(u,'avatar tiny-avatar')}<span><b>${esc(u.display_name)}</b><small>@${esc(u.username||'')}</small></span></div>`).join('')}</div><button id="startConferenceBtn" class="primary full">🚀 شروع کنفرانس</button></div>`,()=>{});$('modalOk').classList.add('hidden');$('modalCancel').textContent='بستن';$('startConferenceBtn').onclick=()=>{closeModal();startConference()};
}
async function startConference(videoMode=true){
  if(!current||current.type!=='group')return showToast('یک گروه را برای کنفرانس باز کن',true);
  if(conference)return showToast('کنفرانس از قبل فعال است');
  conference={room:'conv:'+current.id,peers:new Map(),streams:new Map(),local:null,video:!!videoMode};
  try{conference.local=await navigator.mediaDevices.getUserMedia({audio:true,video:!!videoMode});openConferenceUI();socket.emit('conference:join',{room:conference.room});}catch(e){conference=null;showToast('دسترسی دوربین/میکروفون ممکن نیست',true)}
}
function openConferenceUI(){let el=$('conferenceModal');if(!el){el=document.createElement('div');el.id='conferenceModal';el.className='call-modal';el.innerHTML='<div class="call-card conference-call-card"><div class="call-top"><div><span>👥 کنفرانس زنتو</span><small id="conferenceTimer">00:00</small></div><button id="endConference">×</button></div><div id="conferenceGrid" class="conference-grid"></div><div class="call-actions"><button id="conferenceMute">🎙</button><button id="conferenceCamera">◉</button><button id="conferenceScreen">▣</button><button id="conferenceLeave" class="reject-call">قطع کن</button></div></div>';document.body.appendChild(el);$('endConference').onclick=endConference;$('conferenceLeave').onclick=endConference;$('conferenceMute').onclick=()=>{const t=conference?.local?.getAudioTracks()[0];if(t){t.enabled=!t.enabled;$('conferenceMute').textContent=t.enabled?'🎙':'🔇'}};$('conferenceCamera').onclick=()=>{const t=conference?.local?.getVideoTracks()[0];if(t)t.enabled=!t.enabled};$('conferenceScreen').onclick=()=>toggleConferenceScreen()}
el.classList.remove('hidden');$('conferenceScreen')?.classList.toggle('hidden',!conference.video);$('conferenceCamera')?.classList.toggle('hidden',!conference.video);renderConferenceGrid();}
function renderConferenceGrid(){const grid=$('conferenceGrid');if(!grid||!conference)return;grid.innerHTML='';const addTile=(video,uid,label)=>{const wrap=document.createElement('div');wrap.className='conference-tile-wrap';wrap.dataset.peer=uid??'local';const zoom=document.createElement('button');zoom.type='button';zoom.className='conference-zoom-button';zoom.title='بزرگنمایی';zoom.textContent='⛶';const name=document.createElement('div');name.className='conference-tile-name';name.textContent=label||'کاربر';video.autoplay=true;video.playsInline=true;video.className='conference-tile';if(uid==='local')video.muted=true;video.srcObject=uid==='local'?conference.local:(conference.streams.get(uid)||new MediaStream());zoom.onclick=()=>{const active=wrap.classList.toggle('zoomed');zoom.textContent=active?'⤡':'⛶'};wrap.append(video,name,zoom);grid.appendChild(wrap)};addTile(document.createElement('video'),'local',me?.display_name||'شما');conference.peers.forEach((pc,uid)=>{const u=convs.flatMap(c=>c.members||[]).find(x=>Number(x.id)===Number(uid));addTile(document.createElement('video'),Number(uid),u?.display_name||'کاربر')})}
async function conferenceMakePeer(uid,initiator){if(!conference)return;const pc=new RTCPeerConnection({iceServers:CALL_ICE});conference.peers.set(Number(uid),pc);conference.streams.set(Number(uid),new MediaStream());conference.local.getTracks().forEach(t=>pc.addTrack(t,conference.local));pc.onicecandidate=e=>e.candidate&&socket.emit('conference:ice',{room:conference.room,to:Number(uid),candidate:e.candidate});pc.ontrack=e=>{const st=conference.streams.get(Number(uid));if(st&&!st.getTracks().some(x=>x.id===e.track.id))st.addTrack(e.track);renderConferenceGrid()};pc.onconnectionstatechange=()=>{if(['failed','closed','disconnected'].includes(pc.connectionState)){pc.close();conference.peers.delete(Number(uid));conference.streams.delete(Number(uid));renderConferenceGrid()}};if(initiator){const offer=await pc.createOffer();await pc.setLocalDescription(offer);socket.emit('conference:offer',{room:conference.room,to:Number(uid),offer})}return pc}
async function conferenceHandleOffer(d){if(!conference)return;const pc=await conferenceMakePeer(Number(d.from),false);await pc.setRemoteDescription(new RTCSessionDescription(d.offer));const answer=await pc.createAnswer();await pc.setLocalDescription(answer);socket.emit('conference:answer',{room:conference.room,to:Number(d.from),answer})}
async function endConference(){if(!conference)return;socket.emit('conference:leave',{room:conference.room});conference.peers.forEach(pc=>pc.close());conference.local?.getTracks().forEach(t=>t.stop());conference=null;$('conferenceModal')?.classList.add('hidden');$('conferenceGrid')&&( $('conferenceGrid').innerHTML='')}
async function toggleConferenceScreen(){if(!conference?.local)return;if(!conference.video)return showToast('اشتراک صفحه فقط در کنفرانس تصویری فعال است',true);if(conference.screen){const cam=conference.local.getVideoTracks()[0];conference.peers.forEach(pc=>{const s=pc.getSenders().find(x=>x.track?.kind==='video');if(s&&cam)s.replaceTrack(cam)});conference.screen.getTracks().forEach(t=>t.stop());conference.screen=null;return}try{const st=await navigator.mediaDevices.getDisplayMedia({video:true,audio:true});const tr=st.getVideoTracks()[0];conference.peers.forEach(pc=>{const s=pc.getSenders().find(x=>x.track?.kind==='video');if(s)s.replaceTrack(tr)});conference.screen=st;tr.onended=toggleConferenceScreen}catch(e){showToast('اشتراک صفحه لغو شد',true)}}
if(typeof installCallHandlers==='function'){const _installCalls=installCallHandlers;installCallHandlers=function(){_installCalls();if(!socket)return;socket.on('conference:participants',async d=>{if(!conference||d.room!==conference.room)return;for(const uid of (d.participants||[])){if(Number(uid)!==Number(me.id)&&!conference.peers.has(Number(uid)))await conferenceMakePeer(Number(uid),true)}});socket.on('conference:peer-joined',d=>{if(conference&&d.room===conference.room)renderConferenceGrid()});socket.on('conference:offer',conferenceHandleOffer);socket.on('conference:answer',async d=>{const pc=conference?.peers.get(Number(d.from));if(pc)await pc.setRemoteDescription(new RTCSessionDescription(d.answer))});socket.on('conference:ice',async d=>{const pc=conference?.peers.get(Number(d.from));if(pc&&d.candidate)await pc.addIceCandidate(new RTCIceCandidate(d.candidate)).catch(()=>{})});socket.on('conference:peer-left',d=>{const pc=conference?.peers.get(Number(d.userId));pc?.close();conference?.peers.delete(Number(d.userId));conference?.streams.delete(Number(d.userId));if(conference)renderConferenceGrid()});}}
$('callConference')?.addEventListener('click',openConferenceChooser);$('conferenceCall')?.addEventListener('click',openConferenceChooser);
const _origOpenConvForConference=openConv;openConv=async function(id){const r=await _origOpenConvForConference(id);const bot=current?.type==='direct'&&current.members?.some(x=>Number(x.id)!==Number(me.id)&&x.is_bot);$('callConference')?.classList.toggle('hidden',!!bot||!(current&&(current.type==='group'||current.type==='direct')));$('callAudio')?.classList.toggle('hidden',!!bot||current?.type==='group'||current?.type==='channel');$('callVideo')?.classList.toggle('hidden',!!bot||current?.type==='group'||current?.type==='channel');return r};

/* ================= Zento Stage 1 ================= */
let stage1Theme={accent:'#3390ec',mine:'#2b6cff',theirs:'#ffffff',background:'#dce9f4',bubbleRadius:18,shadow:true,fontSize:15,compact:false};
let stage1Folders=[],stage1Folder='all',stage1Profiles=[],stage1ProfileByConv={};
function stage1ApplyTheme(t){stage1Theme={...stage1Theme,...(t||{})};const r=document.documentElement;r.style.setProperty('--g-accent',stage1Theme.accent);r.style.setProperty('--g-mine',stage1Theme.mine);r.style.setProperty('--g-theirs',stage1Theme.theirs);r.style.setProperty('--g-chat-bg',stage1Theme.background);r.style.setProperty('--g-radius',stage1Theme.bubbleRadius+'px');r.style.setProperty('--g-font',stage1Theme.fontSize+'px');document.body.classList.toggle('g-stage1-shadow',!!stage1Theme.shadow);document.body.classList.toggle('g-stage1-compact',!!stage1Theme.compact)}
function stage1Style(){if(document.getElementById('stage1-style'))return;const st=document.createElement('style');st.id='stage1-style';st.textContent=`
:root{--g-accent:#3390ec;--g-mine:#2b6cff;--g-theirs:#fff;--g-chat-bg:#dce9f4;--g-radius:18px;--g-font:15px}
#messages{background:var(--g-chat-bg)!important;font-size:var(--g-font)}.bubble{border-radius:var(--g-radius)!important}.mine .bubble{background:var(--g-mine)!important}.g-stage1-shadow .bubble{box-shadow:0 2px 10px rgba(0,0,0,.10)}.g-stage1-compact .bubble-row{margin-top:3px!important}.g-stage1-compact .bubble{padding:7px 9px!important}
.stage1-folders{display:flex;gap:6px;overflow:auto;padding:6px 8px;border-bottom:1px solid rgba(0,0,0,.08);scrollbar-width:none}.stage1-folders::-webkit-scrollbar{display:none}.stage1-folder{border:0;border-radius:999px;padding:7px 11px;background:rgba(128,128,128,.10);white-space:nowrap;cursor:pointer}.stage1-folder.active{background:var(--g-accent);color:#fff}.stage1-folder-add{border:1px dashed #aaa;background:transparent}.stage1-theme-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.stage1-theme-grid label{display:flex;flex-direction:column;gap:6px}.stage1-theme-grid input[type=color]{height:42px;padding:3px}.stage1-profile-card{display:flex;align-items:center;gap:10px;padding:10px;border:1px solid rgba(128,128,128,.18);border-radius:14px;margin:7px 0}.stage1-profile-card .stage1-actions{margin-inline-start:auto}.stage1-profile-pill{font-size:11px;padding:3px 7px;border-radius:10px;background:rgba(51,144,236,.12);color:var(--g-accent)}
@media(max-width:700px){.stage1-theme-grid{grid-template-columns:1fr}.stage1-folders{padding-bottom:8px}}
`;document.head.appendChild(st)}
async function stage1Load(){try{const p=await api('/api/preferences');stage1ApplyTheme(p.theme)}catch{}try{stage1Folders=await api('/api/folders')}catch{stage1Folders=[]}try{stage1Profiles=await api('/api/profiles')}catch{stage1Profiles=[]}if(stage1Profiles.length)stage1Profiles.forEach(p=>{if(p.is_default)stage1ProfileByConv._default=p.id});stage1RenderFolders()}
function ensureStoryBar(){return $('storyTopBar')}
async function renderStoryTopBar(){
  let groups=[];try{groups=await loadStories()}catch{}
  const html=`<button class="story-top-card mine" id="storyTopAdd" type="button"><span class="story-top-add-ring">＋</span><span>استوری من</span></button>`+
    groups.map(g=>`<button class="story-top-card ${g.has_unseen?'unseen':''}" data-story-user="${g.user_id}" type="button">${storyRing(g,'story-top-ring')}<span>${esc(g.user_id===Number(me?.id)?'استوری من':g.display_name)}</span></button>`).join('');
  [$('storyTopBar'),$('chatStoryTopBar')].filter(Boolean).forEach(b=>{
    b.innerHTML=html;
    b.classList.add('story-bar-ready');
    b.querySelector('#storyTopAdd')?.addEventListener('click',openStoryComposer);
    b.querySelectorAll('[data-story-user]').forEach(x=>x.onclick=()=>openStories(Number(x.dataset.storyUser)));
  });
}
function stage1EnsureFolderBar(){let b=$('stage1Folders');if(!b&&$('chats')){ $('chats').insertAdjacentHTML('beforebegin','<div id="stage1Folders" class="stage1-folders"></div>');b=$('stage1Folders')}return b}
function stage1RenderFolders(){const b=stage1EnsureFolderBar();if(!b)return;const active=stage1Folder!=='all'&&stage1Folder!=='__add';const folder=stage1Folders.find(x=>String(x.id)===String(stage1Folder));const chips=[{id:'all',name:'همه',icon:'💬'},...stage1Folders.map(f=>({id:String(f.id),name:f.name,icon:f.icon}))];b.innerHTML=chips.map(f=>`<button class="stage1-folder ${String(stage1Folder)===String(f.id)?'active':''}" data-folder="${esc(f.id)}">${f.icon} ${esc(f.name)}</button>`).join('')+`<button class="stage1-folder folder-new" data-folder="__add">＋ پوشه</button>`+(active?`<button class="stage1-folder folder-add-chat" data-folder-action="add-chat">➕ افزودن گفتگو</button>`:'');b.querySelectorAll('[data-folder]').forEach(x=>x.onclick=async()=>{if(x.dataset.folder==='__add'){const name=window.zentoDialog?await window.zentoDialog.prompt('نام پوشه','یک نام برای پوشه وارد کنید'):prompt('نام پوشه:');if(!name?.trim())return;try{const f=await api('/api/folders',{method:'POST',body:JSON.stringify({name:name.trim(),icon:'📁'})});stage1Folders.push(f);stage1Folder=String(f.id);stage1RenderFolders();stage1RenderConvs()}catch(e){showToast(e.message,true)}}else{stage1Folder=x.dataset.folder;stage1RenderFolders();stage1RenderConvs()}});b.querySelector('[data-folder-action="add-chat"]')?.addEventListener('click',()=>stage1AddConversationsToFolder(folder));}
async function stage1AddConversationsToFolder(folder){if(!folder)return;const available=convs.filter(c=>!(folder.conversations||[]).map(Number).includes(Number(c.id)));if(!available.length)return showToast('همه گفتگوها داخل این پوشه هستند');openModal('➕ افزودن گفتگو به پوشه',`<div class="folder-add-head"><b>${esc(folder.icon||'📁')} ${esc(folder.name)}</b><small>گفتگوهایی را که می‌خواهی به این پوشه اضافه شوند انتخاب کن.</small></div><div class="folder-conversation-picks">${available.map(c=>{const other=c.type==='direct'?c.members.find(x=>Number(x.id)!==Number(me.id)):null;const title=c.type==='direct'?(other?.display_name||'گفتگو'):c.name;return `<label class="folder-conversation-item"><input type="checkbox" value="${c.id}"><span>${c.type==='direct'?avatar(other,'avatar tiny-avatar'):`<span class="avatar tiny-avatar">${c.type==='channel'?'📢':'👥'}</span>`}</span><span><b>${esc(title)}</b><small>${c.type==='direct'?'@'+esc(other?.username||''):c.type==='group'?'گروه':'کانال'}</small></span></label>`}).join('')}</div>`,async()=>{const ids=[...document.querySelectorAll('.folder-conversation-picks input:checked')].map(x=>Number(x.value));if(!ids.length)return showToast('حداقل یک گفتگو انتخاب کن');for(const cid of ids)await api(`/api/folders/${folder.id}/conversations/${cid}`,{method:'POST'});stage1Folders=await api('/api/folders');stage1RenderFolders();stage1RenderConvs();closeModal();showToast(`${ids.length} گفتگو به پوشه اضافه شد ✓`)});$('modalOk').textContent='افزودن';}

function stage1RenderConvs(){const visibleConvs=convs.filter(c=>!c._archived);const base=stage1Folder==='all'?visibleConvs:visibleConvs.filter(c=>{const f=stage1Folders.find(x=>String(x.id)===String(stage1Folder));return f?.conversations?.map(Number).includes(Number(c.id))});const list=(activeFilter==='all'?base:base.filter(c=>c.type===activeFilter)).sort((a,b)=>Number(!!b._pinned)-Number(!!a._pinned));const savedItem=activeFilter==='all'?`<button class="chat-item saved-chat-item ${!current?'saved-active':''}" data-saved="1"><div class="avatar saved-avatar">🔖</div><div class="ci"><b>پیام‌های ذخیره‌شده</b><small>فضای شخصی · ذخیره‌ها و یادداشت‌های من</small></div><span class="type-badge">خصوصی</span></button>`:'';$('chats').innerHTML=savedItem+list.map(c=>{const other=c.type==='direct'?c.members.find(x=>Number(x.id)!==Number(me.id)):null;const title=c.type==='direct'?(other?.display_name||'گفتگو'):c.name;const icon=c.type==='channel'?'📢':c.type==='group'?'👥':'گ';const locked=c.stage1Locked?' 🔐':'';return `<button class="chat-item ${current&&Number(current.id)===Number(c.id)?'active':''}" data-id="${c.id}">${c.type==='direct'?avatar(other):`<div class="avatar">${icon}</div>`}<div class="ci"><b>${c._pinned?'📌 ':''}${esc(title)}${locked}${c._muted?' 🔇':''}</b><small>${c.type==='channel'?'کانال':c.type==='group'?`${c.members.length} عضو`:'@'+esc(other?.username||'')} · ${esc(c.last_text||'')}</small></div><span class="type-badge">${c.unread_count>0?`<b class="unread-badge">${c.unread_count>99?'99+':c.unread_count}</b>`:''}${c.type==='channel'?'کانال':c.type==='group'?'گروه':'خصوصی'}</span></button>`}).join('')||'<div class="empty"><span>گفتگویی پیدا نشد</span></div>'}
const _baseStage1RenderConvs=stage1RenderConvs;
stage1RenderConvs=function(){_baseStage1RenderConvs();renderStoryTopBar().catch(e=>console.warn('stories',e));};
renderConvs=stage1RenderConvs;
const originalOpenConv=openConv;
const _zentoOpenConvWithStories=originalOpenConv;
const openConvWithStories=async function(id){const r=await _zentoOpenConvWithStories(id);setTimeout(()=>renderStoryTopBar().catch(()=>{}),80);return r};
async function stage1OpenConv(id){const c=convs.find(x=>Number(x.id)===Number(id));if(!c)return;try{const st=await api('/api/conversations/'+id+'/lock');c.stage1Locked=!!st.locked;if(st.locked){const pin=prompt('🔐 این گفتگو قفل است. PIN را وارد کنید:');if(pin===null)return;await api('/api/conversations/'+id+'/unlock',{method:'POST',body:JSON.stringify({pin})})}}catch(e){showToast(e.message,true);return}try{const p=await api('/api/conversations/'+id+'/profile');if(p)stage1ProfileByConv[id]=p.id}catch{}return openConvWithStories(id)}
openConv=stage1OpenConv;
async function stage1LockMenu(c){const st=await api('/api/conversations/'+c.id+'/lock');if(st.locked){if(confirm('قفل این گفتگو برداشته شود؟')){const pin=prompt('PIN فعلی را وارد کنید:');if(pin===null)return;try{await api('/api/conversations/'+c.id+'/unlock',{method:'POST',body:JSON.stringify({pin})});await api('/api/conversations/'+c.id+'/lock',{method:'DELETE'});c.stage1Locked=false;renderConvs();showToast('قفل برداشته شد')}catch(e){showToast(e.message,true)}}}else{const a=prompt('یک PIN چهار تا هشت رقمی وارد کنید:');if(!a)return;const b=prompt('PIN را دوباره وارد کنید:');if(a!==b)return showToast('PINها یکسان نیستند',true);try{await api('/api/conversations/'+c.id+'/lock',{method:'POST',body:JSON.stringify({pin:a})});c.stage1Locked=true;renderConvs();showToast('گفتگو قفل شد 🔐')}catch(e){showToast(e.message,true)}}}
function removeChatContextMenu(){document.getElementById('chatContextMenu')?.remove()}
function showArchivedChats(){removeChatContextMenu();const archived=convs.filter(c=>c._archived);const body=archived.length?`<div class="archive-hero"><b>🗃️ بایگانی پیشرفته</b><small>${archived.length} گفتگوی بایگانی‌شده · گفتگوها از صفحه اصلی مخفی هستند اما حذف نشده‌اند.</small></div><input id="archiveSearch" class="archive-search" placeholder="جستجو در بایگانی…"><div class="archived-list">${archived.map(c=>{const o=c.type==='direct'?c.members.find(x=>Number(x.id)!==Number(me.id)):null;const t=c.type==='direct'?(o?.display_name||'شخص'):c.name;return `<button class="archived-item" data-archived-id="${c.id}">${c.type==='direct'?avatar(o,'avatar tiny-avatar'):`<span class="avatar tiny-avatar">${c.type==='channel'?'📢':'👥'}</span>`}<span><b>${esc(t)}</b><small>${c.type==='channel'?'کانال':c.type==='group'?`${c.members.length} عضو`:'خصوصی'} · ${esc(c.last_text||'بدون پیام')}</small></span><span class="archive-more">•••</span></button>`}).join('')}</div>`:'<div class="empty"><b>بایگانی خالی است</b><span>هر گفتگویی را از منوی شناور روی چت بایگانی کنی، اینجا می‌بینی.</span></div>';openModal('🗃️ بایگانی گفتگوها',body,()=>{});$('modalOk').classList.add('hidden');$('modalCancel').textContent='بستن';const unarchive=async(c)=>{try{await api(`/api/conversations/${c.id}/user-settings`,{method:'POST',body:JSON.stringify({archived:false})});c._archived=false;showToast('گفتگو از بایگانی خارج شد ✓');closeModal();renderConvs()}catch(e){showToast(e.message,true)}};document.querySelectorAll('[data-archived-id]').forEach(b=>{b.onclick=async()=>{const c=convs.find(x=>Number(x.id)===Number(b.dataset.archivedId));if(c)await unarchive(c)};b.oncontextmenu=async e=>{e.preventDefault();const c=convs.find(x=>Number(x.id)===Number(b.dataset.archivedId));if(!c)return;const menu=document.createElement('div');menu.id='chatContextMenu';menu.className='chat-context-menu';menu.innerHTML=`<div class="chat-context-title">${esc(c.type==='direct'?(c.members.find(x=>Number(x.id)!==Number(me.id))?.display_name||'گفتگو'):c.name)}</div><button data-unarchive>📤 بیرون آوردن از بایگانی</button><button data-open>💬 باز کردن گفتگو</button>`;document.body.appendChild(menu);const r=menu.getBoundingClientRect();menu.style.left=Math.max(10,Math.min(e.clientX,innerWidth-r.width-10))+'px';menu.style.top=Math.max(10,Math.min(e.clientY,innerHeight-r.height-10))+'px';menu.querySelector('[data-unarchive]').onclick=()=>unarchive(c);menu.querySelector('[data-open]').onclick=()=>{removeChatContextMenu();closeModal();openConv(c.id)};setTimeout(()=>{const close=x=>{if(!menu.contains(x.target)){menu.remove();document.removeEventListener('pointerdown',close)}};document.addEventListener('pointerdown',close)},0)}});$('archiveSearch')?.addEventListener('input',e=>{const q=e.target.value.trim().toLowerCase();document.querySelectorAll('.archived-item').forEach(x=>x.classList.toggle('hidden',q&&!x.textContent.toLowerCase().includes(q)))})}

function showChatActionMenu(c,x,y){removeChatContextMenu();const other=c.type==='direct'?c.members.find(x=>Number(x.id)!==Number(me.id)):null;const title=c.type==='direct'?(other?.display_name||'شخص'):c.name;const menu=document.createElement('div');menu.id='chatContextMenu';menu.className='chat-context-menu';menu.innerHTML=`<div class="chat-context-title">${esc(title)}</div><button data-act="pin">📌 ${c._pinned?'برداشتن سنجاق':'سنجاق کردن'}</button><button data-act="mute">${c._muted?'🔊 با صدا':'🔇 بی‌صدا'}</button><button data-act="archive">🗃️ ${c._archived?'خارج کردن از بایگانی':'بایگانی'}</button>${c.type==='channel'?'<button data-act="leave">🚪 ترک کانال</button>':c.type==='group'?'<button data-act="leave">🚪 ترک گفتگو</button><button data-act="delete">🗑️ حذف گفتگو</button>':'<button data-act="delete">🗑️ حذف گفتگو</button>'}`;document.body.appendChild(menu);const r=menu.getBoundingClientRect();let left=Math.min(x||20,innerWidth-r.width-10),top=Math.min(y||20,innerHeight-r.height-10);left=Math.max(10,left);top=Math.max(10,top);menu.style.left=left+'px';menu.style.top=top+'px';menu.querySelectorAll('[data-act]').forEach(b=>b.onclick=async()=>{const a=b.dataset.act;try{if(a==='pin'||a==='mute'||a==='archive'){const k={pin:'pinned',mute:'muted',archive:'archived'}[a];c['_'+k]=!c['_'+k];await api(`/api/conversations/${c.id}/user-settings`,{method:'POST',body:JSON.stringify({[k]:c['_'+k]})});renderConvs();removeChatContextMenu()}else if(a==='leave'||a==='delete'){if(confirm(a==='delete'?'گفتگو حذف شود؟':'از گفتگو خارج شوید؟')){await api(`/api/conversations/${c.id}/self`,{method:'DELETE'});convs=convs.filter(q=>Number(q.id)!==Number(c.id));if(current&&Number(current.id)===Number(c.id)){current=null;$('messages').innerHTML='<div class="empty">گفتگویی انتخاب کنید</div>'}renderConvs();removeChatContextMenu()}}}catch(e){showToast(e.message,true)}});setTimeout(()=>{const close=e=>{if(!menu.contains(e.target)){removeChatContextMenu();document.removeEventListener('pointerdown',close)}};document.addEventListener('pointerdown',close)},0)}
$('chats').addEventListener('contextmenu',e=>{const x=e.target.closest('.chat-item');if(!x)return;e.preventDefault();const c=convs.find(z=>Number(z.id)===Number(x.dataset.id));if(c)showChatActionMenu(c,e.clientX,e.clientY)});
let stage1Long=null;$('chats').addEventListener('pointerdown',e=>{const x=e.target.closest('.chat-item');if(!x)return;stage1Long=setTimeout(()=>{const c=convs.find(z=>Number(z.id)===Number(x.dataset.id));if(c)showChatActionMenu(c,x.getBoundingClientRect().left+20,x.getBoundingClientRect().bottom-6)},700)});['pointerup','pointercancel','pointerleave'].forEach(ev=>$('chats').addEventListener(ev,()=>clearTimeout(stage1Long)));
async function stage1AddToFolder(c){if(!stage1Folders.length){showToast('اول یک پوشه بساز');return}openModal('➕ افزودن به پوشه',`<div class="folder-conversation-picks">${stage1Folders.map(f=>`<label class="folder-conversation-item"><input type="radio" name="targetFolder" value="${f.id}"><span class="avatar tiny-avatar">${esc(f.icon||'📁')}</span><span><b>${esc(f.name)}</b><small>${(f.conversations||[]).length} گفتگو</small></span></label>`).join('')}</div>`,async()=>{const id=Number(document.querySelector('[name=targetFolder]:checked')?.value);if(!id)return showToast('یک پوشه انتخاب کن');await api(`/api/folders/${id}/conversations/${c.id}`,{method:'POST'});stage1Folders=await api('/api/folders');stage1RenderFolders();stage1RenderConvs();closeModal();showToast('به پوشه اضافه شد ✓')});$('modalOk').textContent='افزودن'}
const oldRenderSettings=renderSettings;renderSettings=function(section){if(section!=='appearance'){oldRenderSettings(section);return}const c=$('settingsContent');c.innerHTML=`<div class="settings-content"><h4>🎨 شخصی‌سازی ظاهر</h4><div class="stage1-theme-grid"><label>رنگ اصلی<input id="s1Accent" type="color" value="${esc(stage1Theme.accent)}"></label><label>حباب پیام من<input id="s1Mine" type="color" value="${esc(stage1Theme.mine)}"></label><label>حباب طرف مقابل<input id="s1Theirs" type="color" value="${esc(stage1Theme.theirs)}"></label><label>پس‌زمینه چت<input id="s1Bg" type="color" value="${esc(stage1Theme.background)}"></label><label>گردی حباب<input id="s1Radius" type="range" min="6" max="30" value="${stage1Theme.bubbleRadius}"><span id="s1RadiusV">${stage1Theme.bubbleRadius}px</span></label><label>اندازه متن<input id="s1Font" type="range" min="12" max="22" value="${stage1Theme.fontSize}"><span id="s1FontV">${stage1Theme.fontSize}px</span></label></div><div class="setting-row"><div><b>سایه حباب</b><small>نمایش سایه نرم زیر پیام‌ها</small></div><button id="s1Shadow" class="switch ${stage1Theme.shadow?'on':''}"></button></div><div class="setting-row"><div><b>نمای فشرده</b><small>فاصله کمتر بین پیام‌ها</small></div><button id="s1Compact" class="switch ${stage1Theme.compact?'on':''}"></button></div><button id="s1SaveTheme" class="primary full">ذخیره ظاهر</button></div>`;$('s1Radius').oninput=e=>{$('s1RadiusV').textContent=e.target.value+'px';stage1Theme.bubbleRadius=Number(e.target.value);stage1ApplyTheme(stage1Theme)};$('s1Font').oninput=e=>{$('s1FontV').textContent=e.target.value+'px';stage1Theme.fontSize=Number(e.target.value);stage1ApplyTheme(stage1Theme)};$('s1Shadow').onclick=()=>{stage1Theme.shadow=!stage1Theme.shadow;stage1ApplyTheme(stage1Theme);$('s1Shadow').classList.toggle('on',stage1Theme.shadow)};$('s1Compact').onclick=()=>{stage1Theme.compact=!stage1Theme.compact;stage1ApplyTheme(stage1Theme);$('s1Compact').classList.toggle('on',stage1Theme.compact)};$('s1SaveTheme').onclick=async()=>{stage1Theme.accent=$('s1Accent').value;stage1Theme.mine=$('s1Mine').value;stage1Theme.theirs=$('s1Theirs').value;stage1Theme.background=$('s1Bg').value;stage1ApplyTheme(stage1Theme);await api('/api/preferences',{method:'PUT',body:JSON.stringify({theme:stage1Theme})});showToast('ظاهر ذخیره شد')}};
