function messageSendTone(){if(settings?.notifications?.sounds===false)return;try{const C=window.AudioContext||window.webkitAudioContext;if(!C)return;const c=new C(),o=c.createOscillator(),g=c.createGain();o.frequency.value=520;g.gain.value=.018;o.connect(g);g.connect(c.destination);o.start();o.stop(c.currentTime+.045);setTimeout(()=>c.close().catch(()=>{}),120)}catch{}}
