document.addEventListener('click',async e=>{
  const urlBtn=e.target.closest('[data-bot-url]');
  if(urlBtn){e.preventDefault();const u=urlBtn.dataset.botUrl;if(/^https?:\/\//i.test(u))window.open(u,'_blank','noopener,noreferrer');return;}
  const inline=e.target.closest('[data-bot-inline]');
  if(inline){e.preventDefault();try{inline.disabled=true;await api('/api/messages/'+inline.dataset.msgId+'/bot-button',{method:'POST',body:JSON.stringify({buttonIndex:Number(inline.dataset.buttonIndex)})});showToast('دکمه اجرا شد ✓')}catch(err){showToast(err.message,true)}finally{inline.disabled=false}return;}
  const reply=e.target.closest('[data-bot-reply]');
  if(reply&&current){e.preventDefault();const text=reply.dataset.botReply;try{const out=await api('/api/messages',{method:'POST',body:JSON.stringify({conversationId:current.id,text})});appendMessage(out);scrollBottom()}catch(err){showToast(err.message,true)}}
});
